function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks) {
  return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets: [] };
}

function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews) {
  return {
    id,
    skillId,
    stem,
    options,
    answerIndex,
    reasons,
    difficulty,
    cognitiveProcess: ["生物概念判讀", "證據推理"],
    representationType: "文字與資料判讀",
    misconceptionTargets: [],
    reviews,
    assets: [],
  };
}

function stimulus(id, skillId, type, content, accessibility, questions) {
  return { id, skillId, type, content, accessibility, questions, assets: [] };
}

const lectures = [];

const questions = [];

const stimuli = [];

lectures.push(lecture(
  "BIO_R4_L_S041",
  "BIO_R4_S041",
  ["辨識醣類、蛋白質與脂質在人體中的主要功能。", "依生活情境判斷三類養分的功能，避免把食物名稱直接當成養分類別。"],
  [
    { id: "BIO_R4_L_S041_SEC_01", title: "醣類與日常能量", content: "醣類經消化分解後，可成為細胞呼吸利用的原料，是人體日常活動常用的能量來源。米飯、麵食含有較多澱粉，但食物通常不只含單一養分，判斷時應把食物與其中的養分分開。" },
    { id: "BIO_R4_L_S041_SEC_02", title: "蛋白質與生長修補", content: "蛋白質是形成身體組織的重要材料，生長、受傷後修補與部分生理物質的組成，都需要蛋白質。人體也可能利用蛋白質供能，但這不是課程中判斷其主要功能時的首選。" },
    { id: "BIO_R4_L_S041_SEC_03", title: "脂質與儲能保護", content: "脂質可作為長期能量儲存，也能減少體熱散失並保護部分器官。脂質並非完全有害，攝取量與種類才是健康判斷重點；把所有含油食物一概視為不能攝取並不正確。" },
    { id: "BIO_R4_L_S041_SEC_04", title: "由需求判斷養分", content: "遇到情境題時，先找出身體需求：短時間活動常連結可利用的能量，成長與修補連結蛋白質，長期儲能與保溫連結脂質。題目若問主要功能，不能因三者皆可能供能就忽略差異。" },
  ],
  [
    { id: "BIO_R4_L_S041_EX_01", prompt: "學生長跑前吃含澱粉的餐點，應連結哪項主要功能？", steps: ["辨認澱粉屬於醣類。", "把長跑所需活動能量連結到醣類的主要功能。"], answer: "提供日常活動所需能量", why: "題幹以運動需求為核心，澱粉消化後可提供細胞利用的原料，因此應先判斷為醣類供能，而不是組織修補。" },
    { id: "BIO_R4_L_S041_EX_02", prompt: "成長期學生需要建構新的肌肉組織，哪類養分的角色最直接？", steps: ["找出需求是形成新組織。", "對照蛋白質具有生長與修補材料的功能。"], answer: "蛋白質", why: "形成新組織需要構造材料，蛋白質的主要角色最符合；醣類偏向供能，脂質偏向儲能、保溫與保護。" },
    { id: "BIO_R4_L_S041_EX_03", prompt: "寒冷地區動物皮下有較厚脂肪，可推論脂質有何作用？", steps: ["觀察脂肪位於皮下且環境寒冷。", "由位置與情境連結減少熱散失的功能。"], answer: "保溫", why: "皮下脂肪可減少熱量向外散失，題目並未提供快速運動或傷口修補線索，所以保溫是最直接且唯一的判斷。" },
  ],
  [
    { belief: "醣類只存在甜食中。", whyWrong: "澱粉也屬醣類，米飯與麵食即使不甜仍可含大量澱粉。", correction: "判斷醣類不能只靠甜味，應辨識糖與澱粉等不同形式。" },
    { belief: "蛋白質的唯一功能是讓肌肉變大。", whyWrong: "蛋白質也參與各種組織的形成、成長與受損部位修補。", correction: "把蛋白質理解為身體組織與部分生理物質的重要材料。" },
    { belief: "脂質對人體完全沒有益處。", whyWrong: "適量脂質可儲存能量、保溫並緩衝保護部分內臟器官。", correction: "健康問題在攝取是否適當，不能把脂質本身判定為全然有害。" },
    { belief: "三類養分都可能供能，所以主要功能相同。", whyWrong: "可能供能不代表主要角色相同，蛋白質與脂質另有更具代表性的功能。", correction: "依題幹需求區分醣類供能、蛋白質建構修補與脂質長期儲能。" },
  ],
  [
    { prompt: "米飯中的澱粉主要屬於哪類養分？", answer: "醣類", reason: "澱粉是醣類的一種，不能因米飯不甜就排除醣類。" },
    { prompt: "傷口癒合需要補充哪類構造材料？", answer: "蛋白質", reason: "修補受損組織需要形成細胞與組織的重要材料。" },
    { prompt: "皮下脂肪較厚有助減少哪一種散失？", answer: "體熱散失", reason: "皮下脂肪具有隔熱效果，可協助降低身體熱量向外散失。" },
  ],
));

questions.push(
  question("BIO_R4_Q_041_01", "BIO_R4_S041", "foundation", "人體進行日常活動時，最常優先利用哪類養分提供能量？", ["醣類", "蛋白質", "脂質", "礦物質"], 0, ["醣類是日常活動常用的能量來源。", "蛋白質主要用於組織建構與修補。", "脂質偏向長期儲能與保溫保護。", "礦物質不作為細胞呼吸的供能原料。"], ["題幹問日常活動的主要能量來源，依課程功能配對應選醣類。", "蛋白質偏重組織修補，脂質偏向儲能，礦物質則不作為呼吸供能原料。"]),
  question("BIO_R4_Q_041_02", "BIO_R4_S041", "foundation", "生長期身體形成新的組織，最直接需要下列哪類養分？", ["醣類", "蛋白質", "脂質", "水分"], 1, ["醣類主要支應活動所需能量。", "蛋白質是形成身體組織的重要材料。", "脂質主要涉及儲能保溫與保護。", "水是重要介質但不是組織主要建材。"], ["形成新組織的關鍵詞指向建構材料，因此答案是蛋白質。", "即使生長也需要能量，題目問最直接的組織材料，不能改選醣類。"]),
  question("BIO_R4_Q_041_03", "BIO_R4_S041", "foundation", "皮下脂肪有助保溫，主要呈現脂質的哪一項功能？", ["製造氧氣", "運送神經訊息", "減少體熱散失", "分解澱粉"], 2, ["人體脂質不負責製造氧氣。", "神經訊息不是皮下脂肪的主要功能。", "脂肪層可降低身體熱量向外散失。", "分解澱粉需要消化酵素而非脂肪。"], ["情境明示皮下位置與保溫效果，唯一對應是減少體熱散失。", "其他選項分屬氣體、神經或消化作用，與脂質保溫無直接關係。"]),
  question("BIO_R4_Q_041_04", "BIO_R4_S041", "standard", "運動後肌肉組織需要修補時，哪一組養分與功能配對正確？", ["醣類－形成抗體", "脂質－分解乳糖", "水－建造肌纖維", "蛋白質－提供修補材料"], 3, ["形成抗體不屬醣類的主要角色。", "脂質不能直接分解乳糖。", "水是反應介質但不是肌纖維建材。", "蛋白質可提供組織修補所需材料。"], ["題幹核心是運動後的組織修補，正確配對為蛋白質與修補材料。", "另外三組都把養分與不相符的功能連結，沒有第二個合理答案。"]),
  question("BIO_R4_Q_041_05", "BIO_R4_S041", "standard", "某食物不甜但含有大量澱粉，對其養分類別的判斷何者正確？", ["仍含有大量醣類", "一定不含醣類", "主要成分必為蛋白質", "澱粉屬於礦物質"], 0, ["澱粉本身就是醣類的一種形式。", "甜味不是判斷醣類的唯一依據。", "題幹沒有證據顯示蛋白質為主。", "澱粉是有機養分而非礦物質。"], ["辨識澱粉的分類即可確定食物仍含大量醣類，不受甜味影響。", "錯誤選項都建立在以味覺分類或混淆養分類別，故不能成立。"]),
  question("BIO_R4_Q_041_06", "BIO_R4_S041", "standard", "下列哪個生活現象最能呈現脂質的長期儲能功能？", ["咀嚼使食物變小", "能量攝取過多時部分轉成脂肪儲存", "流汗使皮膚表面降溫", "紅血球運送氧氣"], 1, ["咀嚼是物理性消化現象。", "多餘能量可轉為脂肪作長期儲存。", "流汗降溫屬體溫調節。", "運氧主要是循環系統的工作。"], ["題目問長期儲能，只有多餘能量轉成脂肪儲存直接符合。", "其餘現象分屬消化、體溫與循環，不能證明脂質儲能功能。"]),
  question("BIO_R4_Q_041_07", "BIO_R4_S041", "standard", "比較醣類與脂質的主要功能，下列敘述何者最適當？", ["兩者都只能建造肌肉", "兩者都不能提供能量", "醣類常供日常能量，脂質適合長期儲能", "醣類只保溫，脂質只修補"], 2, ["建造與修補組織主要連結蛋白質。", "醣類與脂質都可能與能量利用有關。", "此敘述正確區分兩者代表性功能。", "保溫與修補的配對方向完全顛倒。"], ["醣類常供日常活動能量、脂質適合長期儲能，這組比較保留共同點與差異。", "只建造肌肉、都不能供能及醣類只保溫等說法，都與養分功能不符。"]),
  question("BIO_R4_Q_041_08", "BIO_R4_S041", "advanced", "登山者需準備當天活動能量，也需長期維持身體組織，哪項解釋最合理？", ["只要脂質即可完成全部功能", "蛋白質只能提供甜味", "醣類主要負責保護內臟", "醣類可供活動能量，蛋白質協助組織維持"], 3, ["單一養分不能概括所有身體需求。", "甜味不是蛋白質的功能判準。", "保護內臟較常連結脂質。", "兩類養分與情境需求配對正確。"], ["題幹同時包含活動能量與組織維持，須分別配對醣類與蛋白質。", "只靠脂質忽略均衡需求；甜味不屬蛋白質功能，保護內臟也不是醣類主責。"]),
  question("BIO_R4_Q_041_09", "BIO_R4_S041", "advanced", "某人攝取足夠熱量但蛋白質長期不足，最可能先影響哪項功能？", ["組織生長與受損修補", "肺泡與血液交換氣體", "光線進入眼球", "汗液在皮膚蒸發"], 0, ["缺乏蛋白質會影響建構與修補材料。", "氣體交換不是由蛋白質攝取單獨決定。", "光線進眼不屬養分的主要功能判斷。", "汗液蒸發不以蛋白質為主要控制因素。"], ["即使總熱量足夠，蛋白質不足仍直接限制新組織形成與修補。", "其餘現象沒有題幹所給營養條件與功能間的直接因果連結。"]),
  question("BIO_R4_Q_041_10", "BIO_R4_S041", "advanced", "若動物在寒季增加皮下脂肪，這項變化最能同時支持哪兩項功能？", ["快速傳導與感光", "儲存能量與減少散熱", "製造尿液與吸收氧氣", "分解蛋白質與合成澱粉"], 1, ["傳導與感光不是脂質層的代表功能。", "皮下脂肪能儲能並具有隔熱效果。", "排尿與吸氧由不同器官系統完成。", "脂質層不負責所列消化與合成作用。"], ["寒季增加皮下脂肪可備用能量並降低散熱，正好涵蓋儲能與隔熱功能。", "快速傳導、製造尿液及分解蛋白質都不是皮下脂肪層的主要作用。"]),
  question("BIO_R4_Q_041_11", "BIO_R4_S041", "transfer", "校隊餐點要兼顧賽前能量與受訓後修補，營養設計的核心原則何者適當？", ["完全排除所有脂質", "只補充水即可", "安排醣類來源並攝取適量蛋白質", "只吃高蛋白而不需其他養分"], 2, ["脂質仍有儲能保護等必要角色。", "水重要但不能取代供能與修補材料。", "此配置分別回應能量與修補需求。", "單一高蛋白飲食無法滿足全部需求。"], ["賽前能量與訓練後修補是兩種需求，應分別配置醣類與蛋白質。", "完全排除脂質、只補水或只吃高蛋白，都不能同時回應供能與修補需求。"]),
  question("BIO_R4_Q_041_12", "BIO_R4_S041", "transfer", "研究者發現某海獸皮下有厚脂肪層，且能在缺食時維持活動，最合理的推論是什麼？", ["脂肪層只負責讓身體變重", "脂肪層可直接製造氧氣", "脂肪層可取代所有蛋白質", "脂肪層兼具隔熱與能量儲備作用"], 3, ["體重增加不能解釋缺食時維持活動。", "脂質不具有直接製造氧氣的功能。", "脂質不能取代組織所需蛋白質。", "兩個觀察分別支持隔熱與儲能功能。"], ["厚皮下層對應寒冷隔熱，缺食仍活動則對應儲存能量的利用。", "隔熱與能量儲備能同時解釋兩項觀察；增重、製氧或取代蛋白質都不能。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S041",
  "BIO_R4_S041",
  "meal-record",
  { title: "健行日餐點紀錄", text: "某班進行半日健行。甲餐含較多飯與地瓜，乙餐含較多豆腐與蛋，丙點心含堅果。教師提醒：三份食物都可能含多種養分，表格只列出相對較突出的養分與觀察到的主要需求。", note: "應以養分主要功能解讀，不把任何食物視為只含單一成分。" },
  { summary: "表格列出三份餐點的突出養分及健行情境需求。", colorIndependent: true, dataFallback: { columns: ["餐點", "相對突出養分", "情境需求"], rows: [["甲餐", "醣類", "健行活動能量"], ["乙餐", "蛋白質", "運動後組織修補"], ["丙點心", "脂質", "較長期能量儲備"]] } },
  [
    question("BIO_R4_SQ_041_01", "BIO_R4_S041", "standard", "依餐點紀錄，哪一餐與健行時常用的活動能量來源配對最直接？", ["甲餐的醣類", "乙餐的蛋白質", "丙點心的脂質", "三餐都只提供水"], 0, ["甲餐醣類與活動能量需求直接配對。", "蛋白質較直接對應組織修補材料。", "脂質在表中偏向較長期能量儲備。", "紀錄沒有支持食物只提供水。"], ["表格把甲餐的突出養分列為醣類，並對應健行活動能量。", "題目問最直接配對，不能因其他餐也可能供能而忽略表格主旨。"]),
    question("BIO_R4_SQ_041_02", "BIO_R4_S041", "advanced", "若學生健行後需要修補受訓肌肉，依表格優先關注哪份餐點？", ["只含水的餐點", "乙餐", "丙點心", "完全不進食"], 1, ["表格沒有列出只含水的餐點。", "乙餐蛋白質較突出並對應組織修補。", "丙點心主要提示脂質儲能功能。", "不進食無法提供組織修補材料。"], ["健行後修補肌肉需要蛋白質，表中乙餐的蛋白質最突出，因此應優先關注乙餐。", "堅果仍有其他養分，但依資料設定，乙餐是最直接的比較選項。"]),
    question("BIO_R4_SQ_041_03", "BIO_R4_S041", "transfer", "根據教師提醒，解讀這份紀錄時最應避免哪一項錯誤？", ["比較不同養分的主要功能", "依情境需求選擇養分", "認定每份食物只含表中那一種養分", "區分短期活動與長期儲能"], 2, ["比較主要功能正是資料判讀所需。", "依情境找需求是合理判讀方法。", "食物通常含多種養分，不能視為單一成分。", "區分兩種能量情境有助正確作答。"], ["教師已明示每份食物都可能含多種養分，因此不可把表中突出成分當成唯一成分。", "比較養分功能、依情境找需求及區分活動與儲能，都是合理的資料判讀步驟。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S048",
  "BIO_R4_S048",
  ["區分酵素加快反應與養分在反應中釋出能量。", "由相同受質、不同反應時間的資料判斷酵素影響速率而非提供額外物質或能量。"],
  [
    { id: "BIO_R4_L_S048_SEC_01", title: "催化回答快慢", content: "酵素是催化劑，核心作用是讓合適反應在較短時間內進行。比較有無酵素的組別時，常看到固定時間內產物較多或達到相同產物量所需時間較短，這些都是速率差異。" },
    { id: "BIO_R4_L_S048_SEC_02", title: "能量來自物質轉換", content: "細胞可從養分的化學反應中釋出並利用能量，酵素則協助這些反應以合適速率進行。酵素不是能量包，也不會因加入較多就憑空增加受質原本含有的總能量。" },
    { id: "BIO_R4_L_S048_SEC_03", title: "相同終點不同時間", content: "若有酵素與無酵素兩組在受質量相同時最終形成相同產物量，但有酵素組較早到達，最直接支持酵素改變反應快慢。不能把較早形成誤解為創造更多總物質。" },
    { id: "BIO_R4_L_S048_SEC_04", title: "描述證據不越界", content: "資料只測產物量時，結論應集中在產物形成速率；若要討論能量，還需要能量轉換或釋放的測量。科學作答要區分觀察值、推論與未測項目，避免用「更有力」取代明確機制。" },
  ],
  [
    { id: "BIO_R4_L_S048_EX_01", prompt: "兩組最終產物同為20克，有酵素組較早到達，酵素改變什麼？", steps: ["比較兩組最終產物量相同。", "再比較達到終點所需時間不同。"], answer: "反應速率", why: "相同終點排除酵素創造額外產物的解釋，而較短時間表示單位時間反應較多，因此證據指向速率增加。" },
    { id: "BIO_R4_L_S048_EX_02", prompt: "學生說酵素使食物中的能量變多，應如何修正？", steps: ["區分食物養分與酵素角色。", "把能量來源與催化功能分別表述。"], answer: "養分是能量來源，酵素只協助反應加快", why: "能量來自養分參與的化學反應，酵素降低反應進行的時間需求，但不會憑空增加養分原本包含的總能量。" },
    { id: "BIO_R4_L_S048_EX_03", prompt: "只測每分鐘產物量，能否直接證明釋放的總能量增加？", steps: ["確認實驗直接測量的是產物量。", "檢查是否有任何能量測量或終點資料。"], answer: "不能", why: "每分鐘產物量可反映速率，卻未直接測量能量，也未比較完整反應的總能量，因此只能支持催化快慢的結論。" },
  ],
  [
    { belief: "酵素本身就是細胞使用的能量。", whyWrong: "酵素是協助反應的物質，細胞利用的能量來自養分等物質轉換。", correction: "分開寫出養分提供可釋放能量、酵素加快相關化學反應。" },
    { belief: "反應較快表示最終產物一定更多。", whyWrong: "若受質量相同且反應完全，快慢不同仍可能到達相同最終產物量。", correction: "先看比較的是固定時間或反應終點，再判斷速率或總量。" },
    { belief: "加入兩倍酵素會讓受質總能量變成兩倍。", whyWrong: "酵素量影響反應處理能力，不會增加受質分子原有的能量總量。", correction: "增加酵素可能提高速率，但能量來源仍受受質種類與數量限制。" },
    { belief: "產物形成快就是已直接測到能量。", whyWrong: "產物量與能量是不同測量，前者不能自動取代後者的證據。", correction: "有產物速率資料就描述催化；要談能量需另有能量測量或明確反應資訊。" },
  ],
  [
    { prompt: "酵素主要改變反應的總量還是快慢？", answer: "快慢", reason: "酵素作為催化劑可提高反應速率，不憑空創造受質或能量。" },
    { prompt: "細胞可利用的能量主要來自哪裡？", answer: "養分的化學反應", reason: "養分轉換可釋出能量，酵素只是協助反應在合適時間進行。" },
    { prompt: "只測產物速率能否證明總能量增加？", answer: "不能", reason: "速率資料沒有直接測量能量，也未必顯示完整反應終點改變。" },
  ],
));

questions.push(
  question("BIO_R4_Q_048_01", "BIO_R4_S048", "foundation", "酵素加入適合的反應後，最直接改變的是哪一項？", ["反應進行的速率", "受質所含元素種類", "產物名稱任意改變", "能量憑空產生"], 0, ["催化劑直接使特定反應進行較快。", "酵素不會改寫受質的元素種類。", "產物由反應路徑決定，不能任意改名。", "能量不會因加入酵素而憑空產生。"], ["酵素的定義性功能是催化，所以最直接影響反應快慢。", "「受質所含元素種類」、「產物名稱任意改變」、「能量憑空產生」涉及元素、產物種類或能量創造，都不是催化作用。"]),
  question("BIO_R4_Q_048_02", "BIO_R4_S048", "foundation", "細胞從養分中取得可利用能量時，酵素主要扮演什麼角色？", ["成為全部能量", "協助相關反應加快", "把能量變成受質", "取代所有養分"], 1, ["酵素不是能量本身。", "酵素催化養分參與的化學反應。", "能量不會被酵素變成反應物。", "酵素不能取代提供物質的養分。"], ["養分是能量來源，酵素則讓能量轉換相關反應能適時進行。", "「協助相關反應加快」保留兩者角色，其他選項都把酵素誤當能量或養分替代物。"]),
  question("BIO_R4_Q_048_03", "BIO_R4_S048", "foundation", "有酵素組較快形成產物，最能支持下列哪個敘述？", ["酵素使受質種類增加", "酵素創造額外原子", "酵素提高反應速率", "酵素一定增加總能量"], 2, ["反應較快不代表受質種類增加。", "催化過程不會憑空創造原子。", "較快形成產物正是速率提高的證據。", "未測能量不能推論總能量增加。"], ["固定時間內較快形成產物，直接反映單位時間反應量增加。", "資料沒有受質種類、原子或能量測量，故「酵素提高反應速率」是唯一受支持結論。"]),
  question("BIO_R4_Q_048_04", "BIO_R4_S048", "standard", "兩組受質量相同且最終產物相同，有酵素組耗時較短，表示什麼？", ["酵素增加了最終物質總量", "酵素成為所有產物", "無酵素組完全不能反應", "酵素縮短達到相同終點所需時間"], 3, ["題幹明示最終產物量相同。", "酵素是催化劑而不是全部產物。", "無酵素組最後仍達相同終點。", "耗時較短正確描述速率差異。"], ["相同終點但時間不同，把差異限定在達到終點的速率。", "「酵素縮短達到相同終點所需時間」完全符合兩項觀察，「酵素增加了最終物質總量」、「酵素成為所有產物」、「無酵素組完全不能反應」都與最終量或無酵素結果衝突。"]),
  question("BIO_R4_Q_048_05", "BIO_R4_S048", "standard", "關於酵素與能量的敘述，哪一項最正確？", ["酵素加快反應，但不憑空提供能量", "酵素量越多，受質總能量必定越多", "酵素就是食物中的醣類", "沒有酵素就不存在任何能量"], 0, ["此項正確區分催化與能量來源。", "酵素量不會改變受質原有總能量。", "酵素多為蛋白質但不等同食物醣類。", "能量存在不取決於是否加入酵素。"], ["酵素影響反應速率，能量則來自反應物的物質轉換。", "「酵素加快反應，但不憑空提供能量」沒有混淆兩者，也未使用必定或不存在等過度敘述。"]),
  question("BIO_R4_Q_048_06", "BIO_R4_S048", "standard", "只記錄每分鐘產物量的實驗，可直接回答哪個問題？", ["受質總能量是否加倍", "酵素是否改變產物形成速率", "酵素的所有原子來源", "人體是否完全不需養分"], 1, ["未直接測量能量，不能判斷加倍。", "每分鐘產物量就是反應速率指標。", "產物速率不會提供所有原子來源。", "單一反應不能回答整體營養需求。"], ["測量項目決定可回答範圍，每分鐘產物量直接對應形成速率。", "「酵素是否改變產物形成速率」與資料一致，「受質總能量是否加倍」、「酵素的所有原子來源」、「人體是否完全不需養分」都超出實驗變因與觀察。"]),
  question("BIO_R4_Q_048_07", "BIO_R4_S048", "standard", "若加入更多酵素後固定時間產物較多，最保守的結論為何？", ["受質含能量變成無限", "新產物種類一定增加", "在該條件下反應速率提高", "酵素已全部變成產物"], 2, ["固定時間資料不能支持能量無限。", "題幹只說產物較多，未說種類改變。", "相同時間形成更多產物表示速率提高。", "催化劑不會因此全部轉成產物。"], ["固定時間內產物量增加，是速率提升的直接操作證據。", "結論應限於受測條件與反應快慢，不延伸到能量、種類或角色互換。"]),
  question("BIO_R4_Q_048_08", "BIO_R4_S048", "advanced", "學生把「酵素催化細胞呼吸」改寫成「酵素提供呼吸能量」，問題在哪裡？", ["細胞呼吸不含化學反應", "酵素不能存在細胞內", "養分完全不參與呼吸", "把加快速率誤寫成能量來源"], 3, ["細胞呼吸包含一連串化學反應。", "細胞內確實有多種酵素。", "養分是細胞呼吸重要反應物來源。", "催化與供能是不同角色。"], ["原句的催化表示協助反應快慢，改寫後卻把酵素當成能量來源。", "「把加快速率誤寫成能量來源」精準指出概念偷換，其他選項反而否定已知生理事實。"]),
  question("BIO_R4_Q_048_09", "BIO_R4_S048", "advanced", "有無酵素兩組在十分鐘與一小時分別不同、相同，最合理解讀為何？", ["酵素使反應較早達到相同終點", "酵素使一小時後產物消失", "無酵素組沒有受質", "酵素增加反應物元素"], 0, ["早期不同而後期相同符合速率差異。", "一小時後相同不表示產物消失。", "無酵素組最後有產物，顯示存在受質。", "資料沒有元素種類增加的證據。"], ["早期產量差反映進行快慢，後期相同則顯示終點未改變。", "「酵素使反應較早達到相同終點」同時解釋兩個時間點，不需要加入物質消失或元素變化。"]),
  question("BIO_R4_Q_048_10", "BIO_R4_S048", "advanced", "為直接檢驗酵素是否增加總釋放能量，現有產物速率資料還缺什麼？", ["更多食物照片", "完整能量測量與反應終點比較", "酵素名稱的字數", "容器外觀顏色"], 1, ["照片不能量化反應能量。", "需直接測能量並比較完整反應結果。", "名稱長短與能量無關。", "容器顏色不是能量證據。"], ["速率與總能量是不同問題，需新增直接能量測量和終點資訊。", "「完整能量測量與反應終點比較」能補足推論所需證據，「更多食物照片」、「酵素名稱的字數」、「容器外觀顏色」都不是相關科學變量。"]),
  question("BIO_R4_Q_048_11", "BIO_R4_S048", "transfer", "工廠加入酵素讓相同原料較快完成製程，最適當的效益描述為何？", ["酵素創造免費原料", "產品元素種類任意增加", "縮短處理時間而不表示憑空增加原料能量", "反應完成後能量必為無限"], 2, ["酵素不會創造製程原料。", "元素種類受原料與反應限制。", "此項正確把效益限定為提高速率。", "任何有限反應都不會產生無限能量。"], ["工業催化的直接效益是相同轉換較快，並非創造物質或能量。", "「縮短處理時間而不表示憑空增加原料能量」符合守恆與催化概念，也沒有誇張推論製程終點。"]),
  question("BIO_R4_Q_048_12", "BIO_R4_S048", "transfer", "兩份相同食物，一份加消化酵素後較快分解，最合理的營養解釋為何？", ["加酵素使食物質量自動加倍", "未加酵素的食物不含能量", "酵素直接成為所有養分", "加酵素改變分解快慢，不代表食物原有總能量增加"], 3, ["酵素加入量不會使食物自動加倍。", "未加酵素仍含原有養分與能量。", "酵素不會取代食物中的全部養分。", "此項正確限制在速率而非總能量。"], ["兩份食物原先相同，差異只有分解速度，不能推成原有能量改變。", "「加酵素改變分解快慢，不代表食物原有總能量增加」保留催化角色，其他選項都違反物質與能量基本概念。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S048",
  "BIO_R4_S048",
  "time-course",
  { title: "有無酵素的時間序列", text: "甲乙兩組含相同種類與數量的受質，溫度、pH與體積一致。甲組加入酵素E，乙組不加。研究者在不同時間測量累積產物量，兩組最後都停止增加，沒有直接測量能量。", note: "累積產物量相同不代表各時間點的反應速率相同。" },
  { summary: "表格比較有酵素與無酵素組在四個時間點的累積產物量。", colorIndependent: true, dataFallback: { columns: ["時間", "甲組有酵素", "乙組無酵素"], rows: [["5分鐘", "12", "3"], ["10分鐘", "20", "8"], ["20分鐘", "20", "15"], ["40分鐘", "20", "20"]] } },
  [
    question("BIO_R4_SQ_048_01", "BIO_R4_S048", "standard", "比較5分鐘資料，加入酵素E最直接造成什麼差異？", ["乙組沒有任何反應", "受質種類完全不同", "甲組憑空得到能量", "固定時間內形成較多產物"], 3, ["乙組已有3單位產物，並非沒有反應。", "題幹明示兩組受質種類相同。", "資料沒有直接測量能量來源。", "甲組12高於乙組3，顯示較快形成產物。"], ["相同五分鐘內甲組累積產物較多，直接支持酵素提高反應速率。", "「受質種類完全不同」、「甲組憑空得到能量」、「乙組沒有任何反應」與控制條件、測量項目或乙組非零數值衝突。"]),
    question("BIO_R4_SQ_048_02", "BIO_R4_S048", "advanced", "40分鐘時兩組產物量相同，最能支持哪一項判讀？", ["酵素主要改變到達相同終點的時間", "酵素讓產物在後期消失", "無酵素組最後沒有產物", "甲組總能量一定是兩倍"], 0, ["兩組終點相同但到達速度不同。", "甲組產物仍維持20，沒有消失。", "乙組40分鐘也達到20。", "資料未測能量且終點產物相同。"], ["甲較早到達20，乙較晚到達20，差異清楚落在反應快慢。", "「酵素主要改變到達相同終點的時間」同時符合完整時間序列，沒有把速率誤當總量或能量。"]),
    question("BIO_R4_SQ_048_03", "BIO_R4_S048", "transfer", "根據材料，哪個結論超出本實驗能直接支持的範圍？", ["甲組早期產物形成較快", "酵素E使反應釋放的總能量增加", "酵素E提高受測反應速率", "兩組最後累積產物相同"], 1, ["早期數值差直接支持此描述。", "實驗沒有直接測量能量，不能得到此結論。", "時間序列可支持催化速率提高。", "40分鐘兩組都為20，資料直接支持。"], ["材料特別註明沒有測量能量，因此總能量增加是超出證據的推論。", "「甲組早期產物形成較快」、「酵素E提高受測反應速率」、「兩組最後累積產物相同」都可由表中時間與產物數值直接讀出或合理概括。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S047",
  "BIO_R4_S047",
  ["設計單一變因的酵素探究並辨識操縱、控制與應變變因。", "選擇合適對照、測量方式與重複程序，使結果能回答研究問題。"],
  [
    { id: "BIO_R4_L_S047_SEC_01", title: "研究問題決定操縱變因", content: "單一變因探究先把問題寫成「某因素是否影響酵素反應速率」。研究者主動改變的因素是操縱變因，例如溫度；每次只改一項，才可把組間差異歸因於它。" },
    { id: "BIO_R4_L_S047_SEC_02", title: "控制其他影響因素", content: "酵素量、受質量、酸鹼值、反應時間與測量方法都可能影響結果。研究溫度時，這些條件需在各組維持相同；所謂公平比較不是讓所有條件都不變，而是只讓操縱變因不同。" },
    { id: "BIO_R4_L_S047_SEC_03", title: "應變變因要能測量", content: "應變變因是用來反映酵素作用的結果，例如每分鐘產物量、固定時間的產物量或受質減少量。只寫「反應好不好」缺乏操作定義，無法讓不同觀察者以相同標準記錄。" },
    { id: "BIO_R4_L_S047_SEC_04", title: "對照與重複提升可信度", content: "不加酵素或維持基準條件的組別可提供比較基準；每組重複測量並取適當代表值，可降低偶然誤差。對照與重複不能補救多個變因同時改變，設計根本仍是單一變因。" },
  ],
  [
    { id: "BIO_R4_L_S047_EX_01", prompt: "研究溫度對酵素速率的影響，各組應改變哪一項？", steps: ["由研究問題找出原因因素。", "確認其餘條件可維持相同。"], answer: "溫度", why: "題目要檢驗溫度效果，因此溫度是唯一操縱變因；若同時改變酵素量，結果就無法判斷是溫度或酵素量造成。" },
    { id: "BIO_R4_L_S047_EX_02", prompt: "固定反應五分鐘後測產物毫升數，應變變因是什麼？", steps: ["找出研究者最後記錄的數值。", "寫出物理量與固定時間條件。"], answer: "五分鐘產物體積", why: "產物體積是隨操縱條件改變而測得的反應結果，且有明確時間與單位，可讓各組以一致方法比較。" },
    { id: "BIO_R4_L_S047_EX_03", prompt: "每組只做一次且數值差異很小，如何改善？", steps: ["辨識單次值可能受偶然誤差影響。", "增加獨立重複並用相同程序測量。"], answer: "各組重複多次並比較代表值", why: "重複可看出結果是否穩定並降低單次偶然值的影響；但重複時仍須維持相同的控制條件與測量方法。" },
  ],
  [
    { belief: "公平實驗表示每一組所有條件完全相同。", whyWrong: "若所有條件都相同，就沒有操縱變因可用來檢驗研究問題。", correction: "只改研究因素，其餘可能影響結果的條件維持一致。" },
    { belief: "同時改溫度與pH可以更快得到兩種結論。", whyWrong: "結果改變時無法分辨是哪個因素或兩者交互造成。", correction: "分成兩次單一變因實驗，分別研究溫度與酸鹼值。" },
    { belief: "只寫反應比較好就算可測量結果。", whyWrong: "好壞沒有共同尺度，不同觀察者可能使用不同判準。", correction: "以固定時間產物量或每分鐘變化量建立明確操作定義。" },
    { belief: "重複很多次就能修正不公平的設計。", whyWrong: "多變因混淆會在每次重複中持續存在，無法靠次數消除。", correction: "先確保單一操縱與控制條件，再用重複測量降低偶然誤差。" },
  ],
  [
    { prompt: "研究pH效果時，操縱變因是什麼？", answer: "pH", reason: "研究問題指定酸鹼值，因此各組只主動改變pH並控制其他條件。" },
    { prompt: "每分鐘產物量屬於哪一類變因？", answer: "應變變因", reason: "它是隨實驗條件變化而被測量的反應結果與速率指標。" },
    { prompt: "各組重複三次的主要目的為何？", answer: "降低偶然誤差影響", reason: "重複結果可檢查穩定性，避免單次異常值主導整體結論。" },
  ],
));

questions.push(
  question("BIO_R4_Q_047_01", "BIO_R4_S047", "foundation", "研究溫度對酵素反應的影響，操縱變因應為何？", ["溫度", "產物量", "反應速率", "記錄次數"], 0, ["溫度是研究者主動改變的因素。", "產物量是用來觀察反應的結果。", "反應速率通常屬於應變變因。", "記錄次數不是此研究的原因因素。"], ["研究問題中的影響因素是溫度，所以它是操縱變因。", "產物量與速率是測量結果，不能與主動改變的條件混淆。"]),
  question("BIO_R4_Q_047_02", "BIO_R4_S047", "foundation", "以每分鐘產物量表示酵素作用時，此數值屬於哪種變因？", ["控制變因", "應變變因", "操縱變因", "無關變因"], 1, ["控制變因是在各組維持一致的條件。", "產物量是隨操縱條件改變而測得的結果。", "研究者並非主動指定產物量。", "產物量正是研究所需資訊。"], ["每分鐘產物量是反應速率指標，會隨實驗處理而變化。", "因此它是應變變因，不是被固定或主動設定的條件。"]),
  question("BIO_R4_Q_047_03", "BIO_R4_S047", "foundation", "研究pH影響時，下列何者最應在各組維持相同？", ["pH", "實驗結論", "酵素量", "各組速率"], 2, ["pH是本研究要改變的操縱變因。", "結論由資料形成，不能預先固定。", "酵素量需控制以免影響速率。", "各組速率是測量結果，不要求相同。"], ["研究pH時只能讓pH系統性不同，酵素量等條件須一致。", "若固定速率或結論就失去探究意義，故「酵素量」唯一適合。"]),
  question("BIO_R4_Q_047_04", "BIO_R4_S047", "standard", "哪一項是可操作且可比較的酵素反應速率指標？", ["反應看起來很好", "酵素似乎很努力", "受質應該很適合", "每分鐘形成的產物毫升數"], 3, ["好沒有客觀共同尺度。", "努力是擬人描述而非測量。", "應該適合不是觀察數值。", "具有時間、物理量與單位，可重複測量。"], ["操作定義需讓不同人能以相同方法得到數值，「每分鐘形成的產物毫升數」符合。", "「反應看起來很好」、「酵素似乎很努力」、「受質應該很適合」都是主觀判斷或推測，不能用來進行量化組間比較。"]),
  question("BIO_R4_Q_047_05", "BIO_R4_S047", "standard", "為何研究溫度時不能同時讓各組酵素量不同？", ["速率差可能同時來自溫度與酵素量", "酵素量增加只使產物顏色變深，速率維持原值", "溫度與酵素量是同一物理量", "產物不能在不同溫度測量"], 0, ["兩個因素同時不同會產生因果混淆。", "酵素量增加可提供更多作用部位，反應速率可能隨之改變。", "兩者是不同種類的變因。", "適當方法仍可在不同溫度測量。"], ["若溫度與酵素量同時改變，觀察差異不能單獨歸因於溫度。", "混淆變因的敘述直接說明因果難以歸屬，其他選項不符合實驗概念。"]),
  question("BIO_R4_Q_047_06", "BIO_R4_S047", "standard", "不加酵素但其他條件相同的一組，主要可提供什麼？", ["新的操縱變因", "沒有酵素時的比較基準", "必定最高的反應速率", "不同種類的受質"], 1, ["研究操縱仍是有無酵素的比較。", "此組顯示背景反應或非酵素變化。", "未加酵素通常不會必定最高。", "題幹要求受質等其他條件相同。"], ["無酵素組能顯示沒有催化時的基準，協助判斷產物是否由酵素增加。", "它不是要更換受質或追求最高值，而是建立有意義的對照。"]),
  question("BIO_R4_Q_047_07", "BIO_R4_S047", "standard", "每組重複三次並取平均，主要改善哪一項？", ["讓操縱變因變多", "保證假設一定正確", "降低單次偶然誤差的影響", "使所有數值完全相同"], 2, ["重複不會增加操縱變因。", "實驗結果仍可能不支持假設。", "多次測量可減少異常單次值影響。", "自然測量通常仍有差異。"], ["重複與平均的功能是提高結果穩定性，降低偶然誤差影響。", "它不能保證理論正確，也不要求每次觀察值完全一致。"]),
  question("BIO_R4_Q_047_08", "BIO_R4_S047", "advanced", "甲組25°C且pH 5，乙組40°C且pH 8，此設計最大的問題為何？", ["沒有使用任何酵素", "沒有測量任何溫度", "兩組條件完全相同", "溫度與pH同時改變，因果無法區分"], 3, ["題幹沒有說未使用酵素。", "25與40°C都是明確溫度。", "兩組至少有兩項條件不同。", "多變因同時改變造成解釋混淆。"], ["比較兩組時溫度與pH都不同，結果無法指定由哪個因素造成。", "「溫度與pH同時改變，因果無法區分」直接指出單一變因原則被破壞，是最核心的設計缺陷。"]),
  question("BIO_R4_Q_047_09", "BIO_R4_S047", "advanced", "研究酵素濃度時，哪一組條件配置最公平？", ["只改酵素濃度，固定受質、pH、溫度與時間", "每組同時改受質與溫度", "濃度越高反應時間越長", "各組使用不同測量方法"], 0, ["此配置只有研究因素不同。", "同時改兩條件會產生混淆。", "時間不同也會影響產物量。", "方法不同使數值缺乏可比性。"], ["研究酵素濃度需控制所有其他可能影響速率的條件。", "「只改酵素濃度，固定受質、pH、溫度與時間」符合單一變因且測量一致，能把差異合理歸因於濃度。"]),
  question("BIO_R4_Q_047_10", "BIO_R4_S047", "advanced", "若量筒最小刻度為1毫升，兩組差異只有0.1毫升，應如何處理？", ["直接宣布差異非常確定", "改用更精密工具並重複測量", "把0.1毫升改寫成10毫升", "省略所有原始紀錄"], 1, ["差異小於刻度，不能高度確定。", "提高解析度與重複可檢查微小差異。", "任意改數值違反誠實記錄。", "刪除紀錄會使結果無法查核。"], ["工具刻度不足以可靠分辨0.1毫升，需更精密測量並增加重複。", "「改用更精密工具並重複測量」正面處理測量限制，其他做法誇大、竄改或隱藏資料。"]),
  question("BIO_R4_Q_047_11", "BIO_R4_S047", "transfer", "要比較兩款含酵素清潔劑分解同種污漬的速率，最佳設計為何？", ["兩款使用不同污漬與水溫", "只觀察包裝顏色", "固定污漬量、水溫與時間，只更換清潔劑", "一款測五分鐘，另一款測一天"], 2, ["污漬與水溫不同會混淆效果。", "包裝顏色不是分解速率指標。", "此設計保留單一產品差異與公平比較。", "反應時間不同使結果不能直接比較。"], ["產品比較需讓受質、環境與時間一致，只改清潔劑種類。", "「固定污漬量、水溫與時間，只更換清潔劑」能把分解差異連結到清潔劑，並可搭配量化污漬變化。"]),
  question("BIO_R4_Q_047_12", "BIO_R4_S047", "transfer", "學生發現各組差異很小，哪個後續步驟最符合科學探究？", ["挑一個喜歡的數值當答案", "改寫數據讓趨勢明顯", "不看工具精度直接下定論", "檢查控制條件、增加重複並報告不確定性"], 3, ["主觀挑值不能代表完整資料。", "竄改數據破壞研究可信度。", "忽略精度會誇大微小差異。", "此程序能查核設計並誠實表達限制。"], ["小差異需要檢查誤差來源與重複性，而不是強行宣稱效果。", "「檢查控制條件、增加重複並報告不確定性」保留原始證據並處理不確定性，符合可重現的探究態度。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S047",
  "BIO_R4_S047",
  "experiment-plan",
  { title: "澱粉酵素探究草案", text: "研究問題為「溫度是否影響澱粉酵素分解澱粉的速率？」四個試管皆加入等量澱粉液與酵素液，pH維持7，分別置於10、20、30、40°C，每隔一分鐘以相同方法檢測剩餘澱粉，並各重複三次。", note: "澱粉消失所需時間越短，代表本實驗定義的反應速率越快。" },
  { summary: "表格列出四組溫度與共同控制條件。", colorIndependent: true, dataFallback: { columns: ["組別", "溫度", "酵素量", "澱粉量", "pH"], rows: [["甲", "10°C", "2毫升", "5毫升", "7"], ["乙", "20°C", "2毫升", "5毫升", "7"], ["丙", "30°C", "2毫升", "5毫升", "7"], ["丁", "40°C", "2毫升", "5毫升", "7"]] } },
  [
    question("BIO_R4_SQ_047_01", "BIO_R4_S047", "standard", "這份探究草案中的操縱變因為何？", ["澱粉量", "酵素量", "溫度", "pH"], 2, ["澱粉量皆為5毫升。", "酵素量皆為2毫升。", "四組只系統性改變溫度。", "四組pH都維持為7。"], ["由表格逐欄比較，只有溫度在四組間不同，因此是操縱變因。", "其餘三欄保持一致，正是用來維持公平比較的控制條件。"]),
    question("BIO_R4_SQ_047_02", "BIO_R4_S047", "advanced", "草案如何把反應速率轉成可測量的應變變因？", ["看試管標籤顏色", "改變每組酵素種類", "詢問學生喜好", "記錄澱粉消失所需時間"], 3, ["標籤顏色不代表澱粉分解。", "更換酵素會增加另一操縱變因。", "喜好是主觀意見而非反應結果。", "時間可依共同檢測方法量化比較。"], ["材料明確定義澱粉消失越快代表速率越快，因此記錄時間可操作。", "「記錄澱粉消失所需時間」具有共同方法與單位，能作為各溫度組的應變變因。"]),
    question("BIO_R4_SQ_047_03", "BIO_R4_S047", "transfer", "若丙組誤加4毫升酵素液，最適當的處理是什麼？", ["重新配置丙組使酵素量與其他組相同", "把紀錄改成2毫升", "保留並只歸因於30°C", "讓丁組也任意多加澱粉"], 0, ["重做可恢復單一變因與公平比較。", "不能竄改實際操作紀錄。", "酵素量不同會混淆溫度效果。", "再增加錯誤只會造成更多混淆。"], ["丙組出現第二個變因，現有結果不能只解釋為溫度差異。", "應誠實記錄操作錯誤並按原定控制量重做，而不是改數字或擴大問題。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S046",
  "BIO_R4_S046",
  ["由酸鹼值與濃度資料判斷酵素反應速率。", "辨識不同酵素適合的酸鹼環境與受質增加後的速率平台。"],
  [
    { id: "BIO_R4_L_S046_SEC_01", title: "酸鹼值影響酵素構造", content: "酵素在某段酸鹼範圍內較能維持適合受質的構造，反應速率因而較高。環境過酸或過鹼都可能降低作用；不同酵素所處器官與構造不同，適合的酸鹼值不必相同。" },
    { id: "BIO_R4_L_S046_SEC_02", title: "由資料找酸鹼趨勢", content: "判讀酸鹼資料時，先比較各組速率，再描述哪個受測值最高及兩側如何變化。若酸鹼值只測整數，最高觀察點不等於已精確找到真正最適值，也不能延伸到其他酵素。" },
    { id: "BIO_R4_L_S046_SEC_03", title: "受質濃度與有效接觸", content: "酵素量固定時，低受質濃度下增加受質，酵素與受質相遇機會提高，速率常上升。當多數酵素作用部位都持續被受質占用，再增加受質對速率的提升就會變小。" },
    { id: "BIO_R4_L_S046_SEC_04", title: "平台與限制因素", content: "速率平台表示在當時條件下受質已不再是主要限制因素，酵素量可能成為限制。若增加酵素後平台上升，可支持此解釋；但若溫度、酸鹼也改變，就不能只把結果歸因於濃度。" },
  ],
  [
    { id: "BIO_R4_L_S046_EX_01", prompt: "pH 5、7、9的速率為3、12、4，本次哪個酸鹼值觀察速率最高？", steps: ["比較三個速率數值。", "把最大值12對應回pH 7。"], answer: "pH 7", why: "本次三個測量點中pH 7速率最高，只能說受測條件下的觀察峰值；pH 6或8未測，仍不能確定精確最適值。" },
    { id: "BIO_R4_L_S046_EX_02", prompt: "受質濃度由1增至3單位時速率上升，可能原因為何？", steps: ["確認酵素量與其他條件固定。", "連結受質增加與有效接觸機會增加。"], answer: "酵素與受質有效接觸機會增加", why: "在尚未達平台的範圍，更多受質可提高與酵素作用部位相遇的機會，因此固定時間內形成較多產物。" },
    { id: "BIO_R4_L_S046_EX_03", prompt: "受質濃度再提高，速率卻維持20不變，最合理解釋為何？", steps: ["辨識連續數值不再上升形成平台。", "判斷受質是否仍為主要限制因素。"], answer: "固定酵素量已限制最高速率", why: "在酵素量固定時，多數作用部位已持續參與反應，再增加受質也難以提高處理速率；此時增加酵素才可能提高平台。" },
  ],
  [
    { belief: "所有酵素都在中性環境作用最好。", whyWrong: "不同酵素的構造與所在環境不同，適合的酸鹼範圍可能偏酸或偏鹼。", correction: "依受測酵素資料判斷，不把單一酵素結果套用全部酵素。" },
    { belief: "酸鹼值越大，酵素速率一定越高。", whyWrong: "酸鹼值代表環境酸鹼程度，不是速率大小；過鹼也可能使速率下降。", correction: "逐點比較實測速率，找出峰值與兩側趨勢，不按pH數字排序答案。" },
    { belief: "受質越多，反應速率會無限增加。", whyWrong: "酵素量固定時作用部位有限，受質過多後速率可能進入平台。", correction: "先看資料是否已達平台，再判斷受質或酵素量何者限制速率。" },
    { belief: "速率平台表示反應完全停止。", whyWrong: "平台表示速率維持近似固定，不代表產物不再形成或數值等於零。", correction: "區分速率不再增加與速率停止；平台仍可持續產生產物。" },
  ],
  [
    { prompt: "pH數字較大是否必定代表酵素速率較快？", answer: "不是", reason: "酸鹼值與速率是不同變項，必須依各組實測反應數值判斷。" },
    { prompt: "固定酵素量下受質持續增加，速率可能出現什麼？", answer: "平台", reason: "作用部位有限，受質不再是限制時速率可能維持近似固定。" },
    { prompt: "平台期增加哪一項較可能提高最高速率？", answer: "酵素量", reason: "增加可用作用部位，可能讓更多受質同時接受催化而提高平台。" },
  ],
));

questions.push(
  question("BIO_R4_Q_046_01", "BIO_R4_S046", "foundation", "某酵素在pH 6、7、8的速率為5、11、7，哪組最高？", ["pH 7", "pH 6", "pH 8", "三組相同"], 0, ["pH 7的速率11是最大值。", "pH 6的速率5較低。", "pH 8的速率7也低於11。", "三組數值明顯並不相同。"], ["比較相同單位的三個速率，最大值11對應pH 7。", "此答案只描述受測三點，不代表其他酸鹼值不可能有更高值。"]),
  question("BIO_R4_Q_046_02", "BIO_R4_S046", "foundation", "固定酵素量時，低濃度範圍增加受質常使速率如何變化？", ["立即歸零", "先上升", "必定下降", "完全無法反應"], 1, ["增加受質不會使速率立即歸零。", "有效接觸增加常使速率先上升。", "低濃度增加受質通常不是必定下降。", "有合適酵素受質仍能進行反應。"], ["在作用部位尚未充分利用時，受質增加提高有效接觸，速率常上升。", "題目限定低濃度範圍，不適用已達平台後的情形。"]),
  question("BIO_R4_Q_046_03", "BIO_R4_S046", "foundation", "受質濃度增加但速率不再上升，這段資料稱為什麼現象？", ["沸騰", "凝固", "速率平台", "蒸散"], 2, ["沸騰是液體相變而非酵素速率。", "凝固也不是此曲線變化的名稱。", "數值維持近似固定形成速率平台。", "蒸散描述水分由生物表面散失。"], ["橫軸增加而縱軸速率維持近似固定，正是速率平台。", "另外三個名詞分屬物理變化或植物水分作用，與資料無關。"]),
  question("BIO_R4_Q_046_04", "BIO_R4_S046", "standard", "關於不同酵素與酸鹼值的關係，下列何者正確？", ["所有酵素只在pH 7作用", "pH越大所有酵素越快", "酸鹼完全不影響酵素", "不同酵素適合的酸鹼範圍可能不同"], 3, ["有些酵素適合偏酸或偏鹼環境。", "pH大小不能直接等同反應速率。", "酸鹼可能影響酵素構造與作用。", "不同構造與環境可造成適合範圍差異。"], ["課程強調不同酵素具有各自適合條件，「不同酵素適合的酸鹼範圍可能不同」表述保留差異。", "「所有酵素只在pH 7作用」、「pH越大所有酵素越快」、「酸鹼完全不影響酵素」使用所有或完全等絕對說法，且與酵素環境適應不符。"]),
  question("BIO_R4_Q_046_05", "BIO_R4_S046", "standard", "某酵素在pH 3速率最高，能直接推論什麼？", ["本次受測範圍以pH 3觀察值最高", "所有酵素都適合強酸", "pH 2的速率一定相同", "此酵素不能再利用"], 0, ["此敘述忠實限定在本次資料範圍。", "單一酵素不能代表所有酵素。", "未測pH 2就不能指定數值。", "酸鹼峰值與是否再利用無直接關係。"], ["資料能支持的最小結論是本次受測範圍的最高觀察值。", "其他選項都跨越酵素種類、未測條件或不同性質，屬過度推論。"]),
  question("BIO_R4_Q_046_06", "BIO_R4_S046", "standard", "受質濃度為4、6、8時速率皆為18，最合理的判讀為何？", ["三組反應都停止", "此範圍已出現速率平台", "受質濃度沒有改變", "酵素量必定為零"], 1, ["速率18表示反應仍在進行。", "受質增加而速率固定符合平台。", "濃度數值4、6、8明顯不同。", "酵素量為零不會有持續速率18。"], ["橫軸濃度增加但速率連續相同，資料特徵就是平台。", "平台不等於停止，反應仍以每單位時間18的速率進行。"]),
  question("BIO_R4_Q_046_07", "BIO_R4_S046", "standard", "在受質過量的平台期，增加何者最可能提高反應速率？", ["移除全部受質", "破壞酵素構造", "增加可作用的酵素量", "同時降低酵素與受質"], 2, ["移除受質會使反應物不足。", "破壞酵素只會降低可用作用部位。", "更多酵素可提供更多作用部位。", "兩者都降低不會提升平台。"], ["平台期受質不再是主要限制，增加酵素量可提高同時處理能力。", "「增加可作用的酵素量」直接增加限制因素，其他操作都減少反應所需成分。"]),
  question("BIO_R4_Q_046_08", "BIO_R4_S046", "advanced", "兩組pH不同且酵素量也不同，為何不能只歸因於酸鹼值？", ["pH無法測量", "酵素不受任何條件影響", "產物沒有質量", "酵素量也可能影響速率"], 3, ["pH可用適當儀器或試紙測量。", "酵素會受環境與用量影響。", "產物仍具有可測量的量。", "兩個變因同時不同會混淆因果。"], ["公平比較需讓除酸鹼外的條件一致，酵素量不同就是混淆變因。", "「酵素量也可能影響速率」指出設計問題，「pH無法測量」、「酵素不受任何條件影響」、「產物沒有質量」都是否定可測量性或基本作用。"]),
  question("BIO_R4_Q_046_09", "BIO_R4_S046", "advanced", "速率隨受質濃度先升後平，最完整的解釋為何？", ["低濃度時接觸增加，高濃度時酵素量成為限制", "受質越多酵素就全部消失", "平台代表沒有任何產物形成", "濃度增加使pH必定變成七"], 0, ["此項分別解釋上升段與平台段。", "受質增加不會使酵素全部消失。", "平台仍有固定速率與產物形成。", "受質濃度不必然決定pH為七。"], ["完整解釋要涵蓋兩段趨勢，「低濃度時接觸增加，高濃度時酵素量成為限制」以限制因素轉換說明最合理。", "「受質越多酵素就全部消失」、「平台代表沒有任何產物形成」、「濃度增加使pH必定變成七」與平台定義或變因關係衝突，不能同時解釋全部資料。"]),
  question("BIO_R4_Q_046_10", "BIO_R4_S046", "advanced", "甲酵素在pH 2較快，乙酵素在pH 8較快，可得到什麼結論？", ["甲乙必定是同一酵素", "兩種酵素適合的酸鹼環境不同", "所有反應都不需受質", "pH 8一定比pH 2溫度高"], 1, ["不同酸鹼反應特徵不支持必定相同。", "兩者最高作用條件分別偏酸與偏鹼。", "酵素反應仍需要相應受質。", "pH與溫度是不同測量變項。"], ["兩酵素速率較高的酸鹼值不同，直接支持適合環境有差異。", "不能把酸鹼值混成溫度，也不能由結果否定受質需求。"]),
  question("BIO_R4_Q_046_11", "BIO_R4_S046", "transfer", "製程已達受質濃度平台，若想測試是否受酵素量限制，應怎麼做？", ["同時改變溫度與pH", "只再增加大量受質", "固定其他條件並增加酵素量", "不記錄任何產物"], 2, ["同時改兩條件無法檢驗單一限制。", "平台期再加受質通常資訊有限。", "平台若隨酵素量提高可支持此假設。", "沒有產物資料就無法比較速率。"], ["檢驗酵素量限制需只操縱酵素量，並維持受質與環境條件一致。", "「固定其他條件並增加酵素量」能產生可比較結果，符合單一變因與限制因素推理。"]),
  question("BIO_R4_Q_046_12", "BIO_R4_S046", "transfer", "胃與小腸環境酸鹼不同，推測兩處消化酵素時最合理的原則為何？", ["兩處酵素必定完全相同", "只看器官大小即可", "pH越高一定消化越完全", "各酵素可能適應所在器官的酸鹼環境"], 3, ["不同環境不支持酵素必定相同。", "器官大小不能決定酵素適合pH。", "pH高低不能直接等同消化程度。", "酵素作用條件可能與所在環境相配合。"], ["生活情境應運用不同酵素適合條件可能不同的概念，而非固定中性。", "「各酵素可能適應所在器官的酸鹼環境」是可檢驗且保留差異的推測，其他選項皆過度簡化。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S046",
  "BIO_R4_S046",
  "two-part-enzyme-data",
  { title: "酵素P的兩階段測試", text: "第一階段固定受質濃度，測量不同pH的速率；第二階段固定pH 6與酵素量，逐步提高受質濃度。兩階段的速率單位相同，但目的不同：前者比較酸鹼環境，後者觀察濃度與平台。", note: "各階段內除表列變因外，其餘條件保持一致。" },
  { summary: "文字表格分列不同pH與不同受質濃度下的反應速率。", colorIndependent: true, dataFallback: { columns: ["階段與條件", "反應速率"], rows: [["第一階段pH 4", "6"], ["第一階段pH 6", "15"], ["第一階段pH 8", "5"], ["第二階段濃度1", "4"], ["第二階段濃度3", "11"], ["第二階段濃度5", "15"], ["第二階段濃度7", "15"]] } },
  [
    question("BIO_R4_SQ_046_01", "BIO_R4_S046", "standard", "第一階段所測三個pH中，哪個反應速率最高？", ["pH 4", "pH 6", "pH 8", "三者相同"], 1, ["pH 4速率只有6。", "pH 6速率15為三者最大。", "pH 8速率5低於另外兩組。", "三組速率數值並不相同。"], ["第一階段數值6、15、5中，最大值15對應pH 6。", "結論只限三個受測pH，不能宣稱精確峰值必定正好是六。"]),
    question("BIO_R4_SQ_046_02", "BIO_R4_S046", "advanced", "第二階段哪兩個受質濃度最能顯示速率已進入平台？", ["濃度1與3", "濃度1與7", "濃度5與7", "濃度3與5"], 2, ["兩者速率4與11仍在增加。", "首尾相差大，不能顯示平台連續。", "濃度增加而速率皆維持15。", "速率由11升到15，仍有增加。"], ["濃度5到7增加時速率保持15，這一段最直接呈現平台。", "平台判斷需要相鄰濃度增加而速率不變，故「濃度5與7」唯一符合。"]),
    question("BIO_R4_SQ_046_03", "BIO_R4_S046", "transfer", "若想提高第二階段的平台並檢驗限制因素，下一步最適當的是什麼？", ["再把受質濃度提高但不改其他項", "改用完全不同的產物量單位", "同時升溫並改變pH", "固定pH與受質過量，增加酵素量"], 3, ["已有平台時只加受質不易檢驗酵素限制。", "改單位不會改變實際反應速率。", "同時改兩環境條件會混淆原因。", "增加酵素可測試作用部位是否為限制。"], ["平台顯示受質可能不再限制，應增加酵素量並固定其他條件。", "若平台上升即可支持酵素量限制，這是最直接的後續檢驗。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S045",
  "BIO_R4_S045",
  ["由溫度與反應速率資料判斷特定酵素的作用趨勢。", "區分低溫減慢反應與高溫可能破壞酵素構造，並限制結論範圍。"],
  [
    { id: "BIO_R4_L_S045_SEC_01", title: "低溫下反應較慢", content: "溫度較低時，分子運動較慢，酵素與受質有效接觸的機會較少，反應速率常降低。低溫通常沒有直接證明酵素永久失去功能；恢復合適溫度後，作用可能再增加。" },
    { id: "BIO_R4_L_S045_SEC_02", title: "升溫與速率增加", content: "在酵素構造尚能維持的範圍內，升高溫度常使分子運動加快，反應速率隨之上升。解讀時必須依實測資料判斷，不能預設溫度越高反應必定永遠越快。" },
    { id: "BIO_R4_L_S045_SEC_03", title: "高溫可能使酵素失活", content: "溫度過高可能改變酵素的立體構造，使作用部位不再適合受質，反應速率便明顯下降。這種下降與低溫造成的暫時減慢機制不同，題目常用加熱後再降溫的結果協助區分。" },
    { id: "BIO_R4_L_S045_SEC_04", title: "資料最高點的限制", content: "一組測量中速率最高的溫度，只能說是本實驗所測條件與溫度間隔中的最高值。若未測相鄰溫度，不能斷言真正最適溫度恰好等於該數值，更不能推論所有酵素相同。" },
  ],
  [
    { id: "BIO_R4_L_S045_EX_01", prompt: "10、20、30、40°C的速率依序為2、6、11、4，哪個溫度觀察值最高？", steps: ["逐一比較四個速率數值。", "找出最大值11所對應的溫度。"], answer: "30°C", why: "在本次四個測量點中，30°C的速率11最高；此結論只描述觀察值，不能宣稱所有酵素真正最適溫度都是30°C。" },
    { id: "BIO_R4_L_S045_EX_02", prompt: "酵素在5°C作用慢，回到25°C後速率恢復，能否說5°C已破壞酵素？", steps: ["比較低溫後恢復的結果。", "判斷作用能力是否永久喪失。"], answer: "不能", why: "回溫後速率恢復表示酵素仍具作用能力，低溫主要使反應暫時變慢；沒有證據支持酵素構造已被永久破壞。" },
    { id: "BIO_R4_L_S045_EX_03", prompt: "加熱到80°C後再降回30°C，反應仍極慢，較合理的解釋為何？", steps: ["注意回到原溫度後速率沒有恢復。", "連結高溫可能改變酵素構造。"], answer: "高溫使酵素失去作用能力", why: "若只是當下溫度效應，回到30°C應可恢復；持續低速支持高溫已改變酵素構造，使其無法與受質適當配合。" },
  ],
  [
    { belief: "溫度越高，酵素反應一定越快。", whyWrong: "超過酵素可維持構造的範圍後，反應速率可能因失活而下降。", correction: "依資料找出上升與下降區段，不把局部趨勢無限延伸。" },
    { belief: "低溫與高溫都一定永久破壞酵素。", whyWrong: "低溫常只使分子運動減慢，高溫才較可能造成構造改變。", correction: "利用回到合適溫度後是否恢復作用，區分暫時減慢與失活。" },
    { belief: "表中最高值就是精確的真正最適溫度。", whyWrong: "測量點之間未必有資料，真正峰值可能位於兩個測量溫度之間。", correction: "表述為本次測量中最高，若要精確定位應縮小溫度間隔再測。" },
    { belief: "一種酵素的溫度結果可套用所有酵素。", whyWrong: "不同酵素的構造與所處環境不同，適合的溫度範圍可能不同。", correction: "結論限定在受測酵素與實驗條件，不進行無證據的普遍化。" },
  ],
  [
    { prompt: "低溫時酵素反應常較慢，是否必定表示酵素被破壞？", answer: "不一定", reason: "低溫可能只降低分子運動，回溫後酵素作用仍可恢復。" },
    { prompt: "高溫後回到原溫仍無作用，可能代表什麼？", answer: "酵素失活", reason: "持續無法作用支持高溫改變酵素構造，而非單純暫時降速。" },
    { prompt: "資料只測每隔10°C，能否確定真正峰值位置？", answer: "不能", reason: "未測的相鄰溫度可能有更高速率，需要縮小間隔才能確認。" },
  ],
));

questions.push(
  question("BIO_R4_Q_045_01", "BIO_R4_S045", "foundation", "某酵素在10°C時反應較慢，最合理的初步解釋是什麼？", ["低溫使分子運動較慢", "低溫必定製造更多產物", "低溫使受質全部消失", "低溫為反應提供能量"], 0, ["低溫常降低有效接觸與反應速率。", "反應較慢不會直接形成更多產物。", "受質不會因低溫而全部消失。", "低溫不是反應能量的供應者。"], ["題幹只指出低溫下速率慢，分子運動減慢是最合理機制。", "其他選項與觀察方向相反，或把溫度錯寫成物質與能量來源。"]),
  question("BIO_R4_Q_045_02", "BIO_R4_S045", "foundation", "酵素反應在30°C速率12、40°C速率7，哪個溫度的觀察速率較高？", ["40°C", "30°C", "兩者皆為零", "無法比較數字"], 1, ["40°C數值7小於12。", "30°C數值12是兩者中較高者。", "表中兩個數值都不是零。", "相同單位的速率數字可以直接比較。"], ["比較12與7即可判定30°C觀察速率較高，不需額外假設。", "此題只問兩個測量點，不等於確認真正最適溫度位置。"]),
  question("BIO_R4_Q_045_03", "BIO_R4_S045", "foundation", "溫度過高使酵素作用部位形狀改變，最可能造成什麼結果？", ["受質種類增加", "酵素提供更多能量", "反應速率下降", "所有產物變回受質"], 2, ["高溫不會因此增加受質種類。", "酵素並不提供反應能量。", "無法適合受質會使催化作用減弱。", "失活不代表產物必定全部逆轉。"], ["作用部位改變會降低與受質配合的機會，因此反應速率下降。", "「受質種類增加」、「酵素提供更多能量」、「所有產物變回受質」都沒有由酵素構造改變到反應結果的合理連結。"]),
  question("BIO_R4_Q_045_04", "BIO_R4_S045", "standard", "某酵素在5°C作用慢，回到25°C後恢復，最適當的判斷為何？", ["5°C已永久分解酵素", "25°C產生了新受質", "低溫讓酵素變成能量", "5°C主要使反應暫時減慢"], 3, ["恢復作用反駁永久破壞。", "回溫不代表產生新的受質。", "酵素不會因低溫變成能量。", "作用恢復支持低溫的暫時效應。"], ["回到25°C後恢復是關鍵證據，表示低溫時酵素仍保有功能。", "「5°C主要使反應暫時減慢」解釋前後變化，其他選項都與恢復作用的觀察衝突。"]),
  question("BIO_R4_Q_045_05", "BIO_R4_S045", "standard", "表中20、30、40°C的速率為6、14、9，能直接得到哪個結論？", ["本次測量以30°C速率最高", "所有酵素最適溫度是30°C", "35°C速率必定等於14", "40°C已使受質消失"], 0, ["三個觀察值中14確實最大。", "單一酵素資料不能代表所有酵素。", "35°C未測，不能指定其速率。", "速率下降不能證明受質已消失。"], ["結論必須忠於資料範圍，只能說本次三個測量點以30°C最高。", "後三項分別過度普遍化、臆測未測數值與錯推物質消失。"]),
  question("BIO_R4_Q_045_06", "BIO_R4_S045", "standard", "酵素在70°C處理後降回30°C仍無作用，哪項解釋最合理？", ["低溫使反應暫停", "高溫可能使酵素構造改變", "受質在降溫後增加", "產物把溫度降低"], 1, ["處理溫度是70°C而非低溫。", "回溫仍無作用支持高溫失活。", "資料未顯示受質數量增加。", "產物不會成為降溫原因。"], ["高溫後即使恢復合適溫度仍無作用，指向酵素構造遭改變。", "「高溫可能使酵素構造改變」能解釋持續失活，其他項目不符合處理條件或缺乏證據。"]),
  question("BIO_R4_Q_045_07", "BIO_R4_S045", "standard", "若要更精確估計峰值在30°C附近的位置，下一步應如何測量？", ["只重複10°C", "刪除所有30°C資料", "增加25至35°C間較密集的溫度點", "把溫度與酸鹼同時改變"], 2, ["只測10°C不能定位30°C附近峰值。", "刪除最高附近資料會減少判斷依據。", "縮小附近測量間隔可提高定位精度。", "同時改酸鹼會混入另一變因。"], ["峰值可能落在既有測量點之間，因此需增加鄰近且較密集的溫度。", "「增加25至35°C間較密集的溫度點」只細化溫度變因，其餘設計無法回答或破壞公平比較。"]),
  question("BIO_R4_Q_045_08", "BIO_R4_S045", "advanced", "甲酵素在35°C最高，乙酵素在50°C最高，最合理的比較結論為何？", ["兩酵素受質必定相同", "乙酵素永遠不會失活", "甲酵素在所有溫度都較快", "不同酵素適合的溫度範圍可能不同"], 3, ["最高溫度不同不能證明受質相同。", "50°C最高不代表任何高溫都不失活。", "資料只給最高位置，未給全範圍速率。", "兩酵素的觀察峰值差異支持此結論。"], ["兩種酵素在相同指標下最高點不同，表示適合溫度可能有差異。", "不能把峰值資訊延伸成受質、永不失活或全溫度快慢的斷言。"]),
  question("BIO_R4_Q_045_09", "BIO_R4_S045", "advanced", "速率由10到30°C上升，40到60°C下降，哪項敘述最符合完整趨勢？", ["升溫先促進反應，過高後可能因失活而下降", "溫度越高反應必定越快", "30°C以上受質一定不存在", "低溫會永久破壞所有酵素"], 0, ["此項同時解釋上升段與下降段。", "此說法與40到60°C下降相反。", "速率下降不能證明受質不存在。", "資料也沒有低溫後永久失活證據。"], ["完整解釋必須涵蓋先升後降，「升溫先促進反應，過高後可能因失活而下降」符合分子運動與高溫失活。", "「溫度越高反應必定越快」、「30°C以上受質一定不存在」、「低溫會永久破壞所有酵素」只延伸單一方向或加入資料無法支持的絕對結論。"]),
  question("BIO_R4_Q_045_10", "BIO_R4_S045", "advanced", "若40°C組的酵素量比其他組多一倍，為何不能直接比較溫度效果？", ["溫度沒有單位", "酵素量也是會影響速率的變因", "產物永遠無法測量", "所有組都必須零度"], 1, ["攝氏溫度具有明確單位。", "酵素量不同會混淆溫度造成的差異。", "產物可依適當方法進行測量。", "零度並非公平比較的必要條件。"], ["要判斷溫度效果，其他可能影響速率的條件應維持一致。", "40°C組酵素量不同，使觀察差異無法單獨歸因於溫度。"]),
  question("BIO_R4_Q_045_11", "BIO_R4_S045", "transfer", "冷藏食品可減慢酵素相關變化，最合理的概念解釋為何？", ["冷藏把酵素全部移除", "冷藏為食品增加受質", "較低溫度常使酵素反應速率降低", "冷藏使所有酵素永久失活"], 2, ["冷藏沒有把食品中的酵素全部移除。", "溫度降低不等於憑空增加受質。", "低溫使反應較慢可延緩相關變化。", "回溫後可能恢復，不能概括永久失活。"], ["冷藏應用利用低溫降低反應速率，而不是必然破壞或移除酵素。", "「較低溫度常使酵素反應速率降低」符合可逆減慢概念，也沒有超出一般冷藏條件作絕對推論。"]),
  question("BIO_R4_Q_045_12", "BIO_R4_S045", "transfer", "一份資料只測20與60°C，若20°C較快，研究者最不應直接宣稱什麼？", ["兩個測量值可以比較", "60°C可能使酵素作用降低", "仍需測其他溫度了解趨勢", "20°C就是精確最適溫度"], 3, ["相同方法得到的兩值可以進行比較。", "高溫作用降低是可檢驗的合理可能。", "只有兩點不足以描繪完整趨勢。", "未測其他溫度不能確定精確峰值。"], ["兩個溫度只能比較彼此，無法排除21至59°C或更低處有更高值。", "因此最不應把20°C直接定為精確最適溫度，需增加測量點。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S045",
  "BIO_R4_S045",
  "temperature-series",
  { title: "酵素T溫度試驗", text: "學生以相同酵素量、受質量、酸鹼條件與反應時間，測量酵素T在五種溫度下每分鐘產物量。每組重複三次後取平均，表格數值僅代表本次受測酵素與所列溫度。", note: "未測溫度沒有資料，不可由折線想像出精確數值。" },
  { summary: "表格列出五個溫度及酵素T每分鐘平均產物量。", colorIndependent: true, dataFallback: { columns: ["溫度", "平均產物量"], rows: [["10°C", "3"], ["20°C", "8"], ["30°C", "15"], ["40°C", "9"], ["50°C", "2"]] } },
  [
    question("BIO_R4_SQ_045_01", "BIO_R4_S045", "standard", "在本次五個測量溫度中，哪一組平均產物量最高？", ["30°C", "10°C", "40°C", "50°C"], 0, ["30°C的平均產物量15是最大值。", "10°C只有3，並非最高。", "40°C為9，低於30°C。", "50°C為2，是表中最低值。"], ["逐列比較平均產物量，最大數值15對應30°C。", "答案只陳述本次測量最高點，不宣稱真正最適溫度精確為30°C。"]),
    question("BIO_R4_SQ_045_02", "BIO_R4_S045", "advanced", "由30到50°C的資料，哪項趨勢描述正確？", ["產物量持續增加", "產物量隨溫度升高而下降", "產物量完全不變", "資料未測任何高溫"], 1, ["數值由15降到9再降到2。", "三個連續測量值呈下降趨勢。", "三個數值明顯不同。", "40與50°C皆已列入測量。"], ["限定30到50°C後，平均產物量依序15、9、2，呈持續下降。", "此區段趨勢可描述，但不能單憑它代表10到30°C也下降。"]),
    question("BIO_R4_SQ_045_03", "BIO_R4_S045", "transfer", "若要判斷真正峰值是否位於30與40°C之間，最適當的追加實驗為何？", ["只測60與70°C", "刪除30°C組", "在31至39°C增加多個測量點", "同時改變受質種類"], 2, ["更高溫不能定位30到40°C間峰值。", "刪除關鍵比較點會損失資料。", "區間內加密測量可找出是否有更高值。", "改受質會使研究問題轉成另一酵素配對。"], ["問題指定30與40°C之間，因此應保持其他條件並在此區間加密。", "「在31至39°C增加多個測量點」直接提高峰值定位解析度，沒有引入新的實驗變因。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S044",
  "BIO_R4_S044",
  ["說明酵素催化反應與專一性的基本概念。", "由受質與產物資料判斷酵素是否適合某反應，並區分催化與供能。"],
  [
    { id: "BIO_R4_L_S044_SEC_01", title: "酵素是生物催化劑", content: "細胞內許多化學反應在一般條件下進行很慢，酵素可加快特定反應，使生命活動能在合適時間內進行。酵素參與反應過程，但不是反應所需能量或產物本身。" },
    { id: "BIO_R4_L_S044_SEC_02", title: "受質、酵素與產物", content: "受質是酵素作用的反應物，經反應後形成產物。判讀圖表時可依箭頭方向辨識受質與產物；酵素若標在箭頭附近，表示協助反應，不能把它誤認為被分解的受質。" },
    { id: "BIO_R4_L_S044_SEC_03", title: "專一性來自適合配合", content: "一種酵素通常只對某一種受質或一類相近受質作用，稱為專一性。若酵素的作用部位與受質不適合配合，反應速率不會因加入該酵素而明顯增加。" },
    { id: "BIO_R4_L_S044_SEC_04", title: "酵素可重複參與", content: "在反應後仍保持適當構造的酵素可再次參與同類反應，所以少量酵素能依序催化許多受質分子。這不代表酵素永遠不變；高溫或不適酸鹼仍可能破壞其作用能力。" },
  ],
  [
    { id: "BIO_R4_L_S044_EX_01", prompt: "甲反應加入酵素後產物較快出現，可得到什麼結論？", steps: ["確認控制組與實驗組的差異是加入酵素。", "比較相同時間內產物出現速度。"], answer: "此酵素加快甲反應", why: "唯一操縱變因是酵素，加入後產物較快形成，支持催化速率增加；資料沒有顯示酵素增加最終可形成的物質種類。" },
    { id: "BIO_R4_L_S044_EX_02", prompt: "酵素E能分解受質甲，卻不能分解受質乙，這呈現何種特性？", steps: ["比較同一酵素對兩種受質的結果。", "將只對特定受質作用連結專一性。"], answer: "專一性", why: "酵素E並非對所有受質都有效，而只對受質甲作用，顯示酵素與受質需適合配合，是專一性的直接證據。" },
    { id: "BIO_R4_L_S044_EX_03", prompt: "反應後仍能回收到酵素E，能否說酵素是反應產物？", steps: ["區分催化劑與產物的角色。", "利用反應後仍可回收的證據判斷。"], answer: "不能，酵素是催化劑", why: "酵素協助受質轉為產物，反應後仍可存在並再次參與；產物則是受質經反應形成的新物質，兩者角色不同。" },
  ],
  [
    { belief: "酵素會為反應提供能量。", whyWrong: "酵素的作用是加快反應，不是產生或供應反應所需能量。", correction: "把酵素定位為催化劑，能量來源與反應物需由題目另行判斷。" },
    { belief: "一種酵素能分解所有受質。", whyWrong: "酵素作用部位需與受質適合配合，通常具有明顯專一性。", correction: "先確認酵素與受質配對，再判斷反應是否會被加速。" },
    { belief: "酵素在每次反應後一定被完全消耗。", whyWrong: "適當條件下酵素反應後仍可保持功能並再次參與同類反應。", correction: "區分可重複利用的催化劑與會被轉變成產物的受質。" },
    { belief: "加入酵素會創造原本不可能形成的任意產物。", whyWrong: "酵素加快特定既有反應，不會把受質任意變成與反應無關的物質。", correction: "由受質與反應路徑判斷可能產物，酵素只影響合適反應的速率。" },
  ],
  [
    { prompt: "酵素加快化學反應的角色稱為什麼？", answer: "催化劑", reason: "酵素能提高特定反應速率，本身並非主要反應產物。" },
    { prompt: "同一酵素只作用某種受質表示何種性質？", answer: "專一性", reason: "只對適合配合的受質作用，是酵素專一性的核心表現。" },
    { prompt: "適當條件下酵素反應後能否再利用？", answer: "通常可以", reason: "酵素是催化劑，未被破壞時可再次參與相同類型反應。" },
  ],
));

questions.push(
  question("BIO_R4_Q_044_01", "BIO_R4_S044", "foundation", "酵素在生物體內最主要扮演下列哪一種角色？", ["加快特定化學反應", "成為所有反應的產物", "提供細胞全部能量", "取代全部受質"], 0, ["酵素是能加快特定反應的催化劑。", "酵素並非所有反應形成的產物。", "細胞能量不是由酵素本身全部提供。", "酵素協助受質反應而不取代受質。"], ["題目問酵素主要角色，催化特定化學反應是唯一正確描述。", "「成為所有反應的產物」、「提供細胞全部能量」、「取代全部受質」混淆產物、能量與受質，均非催化劑的定義。"]),
  question("BIO_R4_Q_044_02", "BIO_R4_S044", "foundation", "在酵素作用的反應中，被酵素作用的物質通常稱為什麼？", ["產物", "受質", "器官", "能量"], 1, ["產物是反應後形成的物質。", "受質是進入反應並接受酵素作用的物質。", "器官不是單一反應物的名稱。", "能量也不是被作用物質的分類。"], ["依反應名詞定義，被酵素辨識並轉變的反應物稱為受質。", "產物位於反應結果端，器官與能量則不符合物質角色。"]),
  question("BIO_R4_Q_044_03", "BIO_R4_S044", "foundation", "某酵素只對受質甲有效，對乙無效，這最能顯示何種性質？", ["可燃性", "導電性", "專一性", "吸水性"], 2, ["資料沒有燃燒現象可判斷。", "酵素是否導電不是題幹重點。", "只作用特定受質直接呈現專一性。", "題目也未比較任何吸水現象。"], ["同一酵素對甲乙結果不同，且只與甲配合，符合酵素專一性。", "「可燃性」、「導電性」、「吸水性」都是材料性質，不能解釋受質選擇性的反應結果。"]),
  question("BIO_R4_Q_044_04", "BIO_R4_S044", "standard", "反應完成後酵素仍可保持作用能力，最合理的解釋為何？", ["酵素就是全部產物", "酵素會變成受質", "酵素提供新的原子", "酵素是催化劑，通常未被反應消耗"], 3, ["產物由受質轉變而來，不等同酵素。", "角色不會因反應完成任意互換。", "酵素不會憑空提供新原子。", "催化劑可在反應後再次參與作用。"], ["反應後仍有作用能力表示酵素未作為受質被耗盡，符合催化劑特性。", "「酵素就是全部產物」、「酵素會變成受質」、「酵素提供新的原子」違反物質角色與反應守恆概念，無法解釋重複作用。"]),
  question("BIO_R4_Q_044_05", "BIO_R4_S044", "standard", "甲組加入酵素，乙組未加；相同時間內甲組產物較多，可推論什麼？", ["此酵素能加快該反應", "酵素讓受質種類增加", "乙組完全沒有受質", "酵素一定是產物"], 0, ["相同時間產物較多表示反應速率較快。", "加入酵素不會增加原有受質種類。", "題幹沒有說乙組缺少受質。", "產物較多不能證明酵素成為產物。"], ["兩組差異為有無酵素，產物生成快慢差異支持酵素催化作用。", "推論應限於速率，不能延伸為改變受質種類或物質角色。"]),
  question("BIO_R4_Q_044_06", "BIO_R4_S044", "standard", "酵素E與受質甲能配合，與受質乙不能配合，哪個預測最合理？", ["E對甲乙速率影響必定相同", "E較可能加快甲的反應", "E會把乙直接變成甲", "E會提供甲反應全部能量"], 1, ["配合情形不同，速率影響不應必定相同。", "適合配合使E較可能催化甲反應。", "酵素不會任意改變受質種類。", "催化不等於提供反應全部能量。"], ["專一性要求酵素與受質適合，因此E對甲的催化預測最合理。", "其他選項忽略配合差異，或加入轉換種類與供能的錯誤概念。"]),
  question("BIO_R4_Q_044_07", "BIO_R4_S044", "standard", "下列哪一個反應式最能正確表示酵素角色？", ["酵素變成受質", "酵素變成全部能量", "受質在酵素協助下形成產物", "產物把酵素永久消耗"], 2, ["酵素與受質角色不同，不會如此互換。", "酵素不是反應全部能量來源。", "此式正確呈現催化與物質轉變。", "產物通常不會因此永久耗盡酵素。"], ["正確表達需讓受質轉變成產物，酵素位於協助反應的位置。", "「受質在酵素協助下形成產物」保留三者角色，其他項目都把酵素錯當被轉變物質。"]),
  question("BIO_R4_Q_044_08", "BIO_R4_S044", "advanced", "若加入兩倍酵素後反應較快，但產物種類不變，最適當的說明是什麼？", ["酵素創造新的物質種類", "酵素改變受質所含元素", "酵素只在反應結束後出現", "酵素影響速率，不任意改變反應產物種類"], 3, ["資料明示產物種類沒有改變。", "題幹沒有元素改變的證據。", "酵素需在反應過程中協助作用。", "此敘述同時符合速率與產物觀察。"], ["觀察是速率增加而產物種類相同，應把酵素作用限於催化。", "「酵素影響速率，不任意改變反應產物種類」完整解釋兩項資料，其他選項都與題幹觀察衝突。"]),
  question("BIO_R4_Q_044_09", "BIO_R4_S044", "advanced", "酵素E反應後被分離，仍能催化另一批相同受質，這項結果支持什麼？", ["酵素可重複參與同類反應", "受質在反應前已消失", "酵素沒有任何專一性", "產物會變回全部受質"], 0, ["再度催化直接支持酵素可重複利用。", "第一批受質已反應不代表反應前消失。", "資料未測試不同受質，不能否定專一性。", "第二次反應不等於產物全部逆轉。"], ["分離後仍有催化能力是可重複參與的直接操作證據。", "其他選項超出實驗比較範圍，或對時間順序與物質轉變作錯誤描述。"]),
  question("BIO_R4_Q_044_10", "BIO_R4_S044", "advanced", "甲酵素能作用澱粉，乙酵素能作用蛋白質；交換受質後皆無作用，最能說明什麼？", ["兩種受質完全相同", "酵素與受質間有特定配合關係", "所有酵素都能作用脂質", "反應不需要任何酵素"], 1, ["交換後結果不同反而顯示受質有差異。", "特定配對能作用，交換後無作用支持專一性。", "資料沒有測試脂質，不能概括。", "原本配對有效顯示酵素確實參與。"], ["原配對有效而交叉配對無效，是酵素受質專一性的典型比較證據。", "結論只能針對被測配對，不能擴張到脂質或否定所有酵素需求。"]),
  question("BIO_R4_Q_044_11", "BIO_R4_S044", "transfer", "清潔劑加入分解蛋白質的酵素，最可能有助去除哪種污漬？", ["純沙粒", "鐵釘鏽斑", "含蛋白質的食物污漬", "玻璃表面刮痕"], 2, ["沙粒不會因蛋白質酵素而被分解。", "鐵鏽不是蛋白質受質。", "污漬成分與酵素受質適合配合。", "刮痕是表面損傷而非可分解受質。"], ["生活應用需先辨識受質，分解蛋白質的酵素適用蛋白質污漬。", "「純沙粒」、「鐵釘鏽斑」、「玻璃表面刮痕」不含相符受質，故不能由專一性預測有效。"]),
  question("BIO_R4_Q_044_12", "BIO_R4_S044", "transfer", "研究未知酵素時，哪種設計最能初步檢驗其受質專一性？", ["只測一種受質一次", "只改變反應時間", "同時改溫度與酸鹼", "在相同條件下分別測試多種受質"], 3, ["單一受質無法比較選擇性。", "只改時間不能辨識適合哪種受質。", "同時改多變因會干擾受質比較。", "固定條件比較多受質可檢驗選擇性。"], ["專一性是對不同受質的選擇差異，因此需在相同條件下逐一比較。", "「在相同條件下分別測試多種受質」保留公平比較，其他設計不是缺少比較就是混入額外變因。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S044",
  "BIO_R4_S044",
  "substrate-test",
  { title: "酵素E受質測試", text: "研究小組在相同溫度與酸鹼條件下，將等量酵素E分別加入三種受質。十分鐘後記錄產物量；另設不加酵素E的甲受質組作對照。所有數值為原創教學資料，只用來判斷催化與專一性。", note: "產物量越大表示在固定時間內反應進行越多。" },
  { summary: "表格比較酵素E對三種受質及無酵素對照的產物量。", colorIndependent: true, dataFallback: { columns: ["組別", "受質", "酵素E", "產物量"], rows: [["一", "甲", "加入", "24"], ["二", "乙", "加入", "1"], ["三", "丙", "加入", "0"], ["四", "甲", "未加入", "2"]] } },
  [
    question("BIO_R4_SQ_044_01", "BIO_R4_S044", "standard", "比較組別一與四，最能支持哪一項結論？", ["產物會阻止所有反應", "甲受質只在黑暗中反應", "酵素E會變成甲受質", "酵素E能加快甲受質反應"], 3, ["表格沒有測試產物抑制作用。", "資料沒有操縱或記錄光照。", "酵素與受質是不同反應角色。", "加入E後相同時間產物量明顯增加。"], ["一與四只有酵素E有無的主要差異，產物量差支持催化甲反應。", "結論應限於速率，不能加入光線、角色互換或抑制等未測因素。"]),
    question("BIO_R4_SQ_044_02", "BIO_R4_S044", "advanced", "由三種受質的結果判斷，酵素E最適合與哪種受質配合？", ["受質甲", "受質丙", "受質乙", "三者完全相同"], 0, ["甲組產物量遠高於乙與丙。", "丙組沒有觀察到產物形成。", "乙組只有極少量產物，證據較弱。", "三組產物量並不相同。"], ["固定條件下甲組產物量最高，表示E對甲的催化效果最明顯。", "此判讀比較相同時間的產物量，不需要假定不同的測量單位。"]),
    question("BIO_R4_SQ_044_03", "BIO_R4_S044", "transfer", "若要確認組別二的少量產物是否來自測量誤差，下一步何者最佳？", ["刪除所有對照組", "重複組別二並增加未加酵素的乙受質對照", "同時更換溫度與受質", "直接宣布E能完全分解所有受質"], 1, ["刪除對照會降低判讀可靠性。", "重複與對照可檢查少量產物是否穩定。", "同時改兩因素無法釐清誤差來源。", "一次少量結果不能支持全面結論。"], ["釐清小差異需重複測量並建立相同受質的無酵素基準。", "「重複組別二並增加未加酵素的乙受質對照」能區分背景值與酵素作用，其他方案都會減少證據品質。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S043",
  "BIO_R4_S043",
  ["區分食物與養分兩個不同層次的概念。", "閱讀食品或實驗資料時，能由食物辨識其中可能含有的多種養分。"],
  [
    { id: "BIO_R4_L_S043_SEC_01", title: "食物是攝取的材料", content: "食物是人實際吃下的材料，例如飯、蛋、牛奶或蔬菜。食物常由許多物質組成，還具有形狀、氣味與口感。把飯、蛋直接列成養分類別，會混淆日常名稱與生物學分類。" },
    { id: "BIO_R4_L_S043_SEC_02", title: "養分是可利用成分", content: "養分是食物中能被身體利用的成分，包括醣類、蛋白質、脂質、維生素、礦物質與水。同一種養分可存在於不同食物，同一種食物也可能同時含有數類養分。" },
    { id: "BIO_R4_L_S043_SEC_03", title: "主要含有不等於只有", content: "營養資料常用「富含」或「主要提供」描述某食物的突出成分，這不代表其中只有一種養分。解題時應保留資料限定，不能把相對含量較多誇大成其他成分完全不存在。" },
    { id: "BIO_R4_L_S043_SEC_04", title: "由問題層次選答案", content: "題目問吃了什麼，答案應是食物名稱；題目問攝取何種成分或功能來源，答案才是養分類別。先辨認問題在日常材料或成分層次，可排除看似相關但層次不一致的選項。" },
  ],
  [
    { id: "BIO_R4_L_S043_EX_01", prompt: "午餐吃了飯、蛋和青菜，其中「蛋」屬於食物還是養分名稱？", steps: ["確認蛋是實際攝取的材料名稱。", "與蛋白質等成分類別分開。"], answer: "食物", why: "蛋是可直接描述餐點內容的食物；蛋中含蛋白質等養分，但不能因名稱相近就把整顆蛋等同於單一養分。" },
    { id: "BIO_R4_L_S043_EX_02", prompt: "牛奶標示含蛋白質、脂質、鈣與水，可得出什麼概念？", steps: ["列出同一食品標示的多種成分。", "判斷食物與養分不是一對一關係。"], answer: "一種食物可含多種養分", why: "資料在同一份牛奶中列出不同養分類別，直接否定食物只含一種養分的說法，也顯示食物是多種成分的組合。" },
    { id: "BIO_R4_L_S043_EX_03", prompt: "題目問米飯主要提供哪類養分，應回答米飯還是醣類？", steps: ["辨認問題要求的是養分類別。", "由米飯富含澱粉且澱粉屬醣類作答。"], answer: "醣類", why: "米飯是題幹中的食物，題目要求其中主要養分；澱粉分類為醣類，所以答案需提升到成分類別而非重複食物名稱。" },
  ],
  [
    { belief: "食物名稱就是養分名稱。", whyWrong: "飯、蛋與蔬菜是攝取材料，醣類與蛋白質才是成分類別。", correction: "先問是否能直接吃下；食物可吃下，養分則是食物中的可利用成分。" },
    { belief: "一種食物只能含一種養分。", whyWrong: "天然或加工食物通常同時含水、醣類、蛋白質等多種成分。", correction: "用含量多寡描述突出養分，不把食物與單一成分畫上等號。" },
    { belief: "富含蛋白質表示完全沒有其他養分。", whyWrong: "富含只比較相對含量或營養特色，不代表其他成分的含量為零。", correction: "保留語句的程度限制，把富含理解為較突出而非唯一存在。" },
    { belief: "同一養分只能來自一種食物。", whyWrong: "蛋白質可來自蛋、豆類等不同食物，醣類來源也不只一種。", correction: "食物與養分是多對多關係，應依資料判斷而非固定一對一配對。" },
  ],
  [
    { prompt: "牛奶在概念上屬於食物還是養分？", answer: "食物", reason: "牛奶是可攝取的材料，其中同時含有多種可利用養分。" },
    { prompt: "蛋白質在概念上屬於食物還是養分？", answer: "養分", reason: "蛋白質是許多食物中可被人體利用的一類成分。" },
    { prompt: "富含鈣是否表示食物只含鈣？", answer: "不是", reason: "富含表示鈣相對突出，不能推論其他所有成分完全不存在。" },
  ],
));

questions.push(
  question("BIO_R4_Q_043_01", "BIO_R4_S043", "foundation", "下列何者是食物名稱，而不是養分類別？", ["豆腐", "醣類", "礦物質", "脂質"], 0, ["豆腐是可直接攝取的食物。", "醣類是食物中的養分類別。", "礦物質是人體所需養分類別。", "脂質也是一類可利用養分。"], ["四個選項中只有豆腐描述實際攝取材料，其餘皆是養分類別。", "判斷不需猜豆腐成分，只要區分日常食物名稱與成分類別即可。"]),
  question("BIO_R4_Q_043_02", "BIO_R4_S043", "foundation", "下列何者屬於食物中可被人體利用的養分？", ["便當盒", "蛋白質", "筷子", "餐桌"], 1, ["便當盒是容器而不是養分。", "蛋白質是可被人體利用的養分。", "筷子是餐具而不是食物成分。", "餐桌不會成為人體所需養分。"], ["蛋白質是食物成分，消化後可供人體吸收與利用。", "便當盒、筷子與餐桌都是用餐環境中的物品，不會成為人體可利用的養分。"]),
  question("BIO_R4_Q_043_03", "BIO_R4_S043", "foundation", "一杯牛奶同時含蛋白質、脂質、鈣與水，這最能說明什麼？", ["牛奶不是食物", "所有養分功能相同", "一種食物可含多種養分", "每種養分只存在牛奶中"], 2, ["牛奶仍是可攝取的食物。", "列出多種成分不代表功能相同。", "同一牛奶中確實列出多類養分。", "資料沒有排除其他食物含這些養分。"], ["題幹以同一杯牛奶列出四類成分，直接支持一食物含多養分。", "不能由單一例子推成養分只存在牛奶，亦不能混淆存在與功能。"]),
  question("BIO_R4_Q_043_04", "BIO_R4_S043", "standard", "題目問「早餐從哪一種食物攝取較多醣類」，哪個回答層次正確？", ["回答醣類能供能", "回答人體需要養分", "回答早餐很重要", "回答早餐中的飯糰"], 3, ["此句回答功能而非食物來源。", "此句只重述一般營養需求。", "此句未指出任何具體食物。", "飯糰是題目要求的食物層次答案。"], ["問題要求哪一種食物，因此應選具體餐點材料飯糰，而非功能敘述。", "先辨認問句層次即可排除三個雖與營養相關卻沒有回答來源的選項。"]),
  question("BIO_R4_Q_043_05", "BIO_R4_S043", "standard", "食品標示寫「本品富含蛋白質」，最合理的解讀為何？", ["蛋白質是較突出的成分之一", "食品內只有蛋白質", "蛋白質就是食品名稱", "食品完全不含水"], 0, ["富含表示蛋白質含量或特色較突出。", "富含不表示其他成分皆為零。", "蛋白質是養分類別而非商品名稱。", "標示沒有提供完全無水的證據。"], ["富含是程度描述，正確解讀需保留其他成分仍可能存在。", "後三項把突出誇大成唯一、混淆名稱，或加入標示未給的資訊。"]),
  question("BIO_R4_Q_043_06", "BIO_R4_S043", "standard", "「雞蛋含有蛋白質」這句話中，兩個名詞的概念關係何者正確？", ["兩者都是餐具", "雞蛋是食物，蛋白質是養分", "雞蛋是養分，蛋白質是食物", "兩者都是器官"], 1, ["雞蛋與蛋白質都不是餐具。", "此項正確區分材料與其中成分。", "此項把食物與養分層次顛倒。", "兩個名詞都不屬人體器官。"], ["語句的含有關係表示雞蛋是整體食物，蛋白質是其中養分。", "名稱都有蛋字不代表概念相同，須依食物與成分的層次判斷。"]),
  question("BIO_R4_Q_043_07", "BIO_R4_S043", "standard", "兩種不同食物都檢測到脂質，最適當的結論是什麼？", ["兩種食物必定完全相同", "脂質不是養分", "同一養分可存在於不同食物", "每種食物只含脂質"], 2, ["共有一成分不代表所有性質相同。", "脂質是人體可利用的養分之一。", "檢測結果直接支持此共同存在關係。", "檢出脂質不能排除其他養分。"], ["兩份食物都檢出同一類養分，足以支持同一養分有多種來源。", "資料不能證明食物完全相同或只含脂質，結論不可超出證據。"]),
  question("BIO_R4_Q_043_08", "BIO_R4_S043", "advanced", "某表把飯、魚、青菜列在直欄，把醣類與蛋白質列在橫列，這個表主要比較什麼？", ["三個器官的功能", "兩種餐具的材質", "人體不同年齡", "不同食物所含養分"], 3, ["飯魚青菜並非人體器官。", "醣類蛋白質也不是餐具材質。", "資料沒有任何年齡分類。", "直欄食物與橫列養分形成含量比較。"], ["表格兩軸分別是食物與養分，交叉欄位自然用來比較成分。", "「三個器官的功能」、「兩種餐具的材質」、「人體不同年齡」都不符合列名與欄名，無法解釋表格結構。"]),
  question("BIO_R4_Q_043_09", "BIO_R4_S043", "advanced", "小明說「我今天吃了蛋白質，所以沒有吃食物」，應如何修正？", ["蛋白質是食物中的養分，實際吃的是含蛋白質的食物", "蛋白質是一種餐具，所以不能吃", "所有食物都只叫蛋白質", "吃蛋白質代表完全沒有攝取水"], 0, ["此句正確區分攝取材料與其中成分。", "蛋白質不是餐具而是養分。", "食物名稱不會全部變成養分名稱。", "含蛋白質不能推論完全沒有水。"], ["日常表達可說攝取蛋白質，但概念上是吃下含蛋白質的食物。", "「蛋白質是食物中的養分，實際吃的是含蛋白質的食物」保留語意並修正層次，其他項目增加新的錯誤分類或推論。"]),
  question("BIO_R4_Q_043_10", "BIO_R4_S043", "advanced", "檢驗甲食物含澱粉與水，乙食物含蛋白質與水，哪項比較有證據支持？", ["甲乙完全沒有共同成分", "甲乙都含水但突出養分不同", "甲只是一種養分而非食物", "乙必定不能提供任何能量"], 1, ["兩者都有水，並非沒有共同成分。", "檢測結果逐項支持此比較。", "甲已被題幹定義為受測食物。", "含蛋白質不能推出完全不供能。"], ["先找共同項水，再比較澱粉與蛋白質差異，即可得到「甲乙都含水但突出養分不同」。", "其他敘述或忽略共同資料、混淆層次，或使用資料無法支持的必定。"]),
  question("BIO_R4_Q_043_11", "BIO_R4_S043", "transfer", "設計營養分類海報時，哪種排版最能正確呈現食物與養分關係？", ["把每種食物固定配唯一養分", "將餐具列為第七大養分", "用連線呈現一食物可含多種養分", "把所有養分改成食物商品名"], 2, ["固定一對一會扭曲實際多成分關係。", "餐具不屬於可利用養分類別。", "多條連線可表達食物與養分多對多。", "商品名不能取代生物學成分類別。"], ["海報要呈現概念關係，多條連線最能表達一種食物含多種養分。", "其餘方案都把分類簡化錯誤，或把非養分物品與商品名稱混入。"]),
  question("BIO_R4_Q_043_12", "BIO_R4_S043", "transfer", "市場推出「只有一種養分的完整餐」，未提供檢測資料，最科學的態度為何？", ["只看名稱就相信", "因為是餐點就必定只有一種", "先認定其他養分都為零", "檢查成分資料再判斷宣稱是否成立"], 3, ["商品名稱不是成分證據。", "餐點通常更可能包含多種物質。", "沒有檢測不能把未列成分視為零。", "查核成分才能評估單一養分宣稱。"], ["食物通常是多種成分組合，特殊宣稱需要成分或檢測資料支持。", "「檢查成分資料再判斷宣稱是否成立」保留證據判斷，其他選項都在資料不足時先接受絕對說法。"]),
);

stimuli.push(stimulus(
  "BIO_R4_ST_S043",
  "BIO_R4_S043",
  "food-label-comparison",
  { title: "三份點心成分摘要", text: "營養社將三份點心送驗，表格只列出本次檢出的部分成分。甲點心是地瓜，乙點心是無糖豆漿，丙點心是原味優格。檢出符號代表含有該成分，不代表未列出的所有成分都不存在。", note: "食物名稱與養分類別分欄呈現，資料不以顏色區分。" },
  { summary: "三種點心與部分檢出養分的文字表格。", colorIndependent: true, dataFallback: { columns: ["食物", "檢出成分一", "檢出成分二"], rows: [["地瓜", "醣類", "水"], ["無糖豆漿", "蛋白質", "水"], ["原味優格", "蛋白質", "礦物質"]] } },
  [
    question("BIO_R4_SQ_043_01", "BIO_R4_S043", "standard", "表格中的「地瓜」與「醣類」分別屬於哪個概念層次？", ["器官與細胞", "養分與食物", "食物與養分", "餐具與食物"], 2, ["兩個詞都不是器官細胞配對。", "此項把兩個概念的順序顛倒。", "地瓜是食物，醣類是其中養分類別。", "地瓜不是餐具，醣類也不是食物名。"], ["依表格欄名可知地瓜列在食物欄，醣類列在檢出成分欄。", "答案只涉及概念分類，不需假設地瓜還有多少未列出的成分。"]),
    question("BIO_R4_SQ_043_02", "BIO_R4_S043", "advanced", "根據表格，哪一項關於養分來源的敘述有直接證據？", ["水只存在地瓜中", "三種食物成分完全相同", "優格只含礦物質", "蛋白質可存在於豆漿與優格"], 3, ["豆漿欄也檢出水，所以此項錯誤。", "三列檢出的成分組合並不相同。", "優格同時列有蛋白質與礦物質。", "豆漿與優格兩列都列出蛋白質。"], ["比較三列可見蛋白質同時出現在豆漿和優格，支持多種來源。", "「水只存在地瓜中」、「優格只含礦物質」、「三種食物成分完全相同」忽略表中另一格資料，或把部分摘要誇大為唯一成分。"]),
    question("BIO_R4_SQ_043_03", "BIO_R4_S043", "transfer", "若要判斷地瓜是否含少量蛋白質，現有表格為何不足？", ["表格只列部分檢出成分，未完整呈現含量", "蛋白質不屬養分", "地瓜不是食物", "表格沒有使用不同顏色"], 0, ["部分摘要無法證明未列成分為零。", "蛋白質確實是一類養分。", "地瓜在材料中明確被列為食物。", "資料已用文字呈現，不需依賴顏色。"], ["材料明示只列部分成分，因此未出現蛋白質不能等同檢驗為零。", "要回答少量是否存在，仍需完整成分或更精確的檢測資料。"]),
  ],
));

lectures.push(lecture(
  "BIO_R4_L_S042",
  "BIO_R4_S042",
  ["說明維生素、礦物質與水在人體中的基本角色。", "由缺乏或流失情境判斷適當養分需求，不把這三類物質誤當主要能量來源。"],
  [
    { id: "BIO_R4_L_S042_SEC_01", title: "維生素的調節角色", content: "維生素種類很多，人體所需量通常不大，卻參與維持正常生理作用。不同維生素的角色不完全相同，因此不能把任何一種維生素說成能包辦所有功能，也不能因需求量少就認為不重要。" },
    { id: "BIO_R4_L_S042_SEC_02", title: "礦物質的多樣功能", content: "礦物質包括鈣、鐵等多種物質。鈣與骨骼、牙齒的構成和正常生理作用有關；鐵是血紅素的重要成分。礦物質不是燃料，題目若出現骨骼或運氧線索，應辨識其特定角色。" },
    { id: "BIO_R4_L_S042_SEC_03", title: "水是反應與運輸介質", content: "水是人體的重要組成，也是許多物質溶解、運輸及化學反應進行的環境。水還參與體溫調節，例如汗液蒸發能帶走熱量；但水本身不會像醣類一樣經分解提供能量。" },
    { id: "BIO_R4_L_S042_SEC_04", title: "需求量不等於重要性", content: "判斷養分重要性不能只看每日需要的質量。水的需求量相對大，某些維生素與礦物質需求量小，三者缺乏都可能影響正常生理。合理飲食應兼顧種類與適量，而非追求單一補充品越多越好。" },
  ],
  [
    { id: "BIO_R4_L_S042_EX_01", prompt: "學生大量流汗後口渴，最直接需要補充哪一種物質？", steps: ["辨認流汗造成水分由體內流失。", "將流失物質與補充需求直接配對。"], answer: "水", why: "大量流汗首先造成水分流失，水又是體液與運輸介質，因此補水是題幹資訊支持的直接需求，而不是補充供能養分。" },
    { id: "BIO_R4_L_S042_EX_02", prompt: "檢查發現血紅素合成所需的鐵不足，鐵屬於哪類養分？", steps: ["辨認鐵是一種化學元素。", "將人體所需的鐵歸入礦物質。"], answer: "礦物質", why: "鐵不是維生素、醣類或水，而是人體需要的礦物質之一；題幹的血紅素線索也支持鐵與運氧能力相關。" },
    { id: "BIO_R4_L_S042_EX_03", prompt: "某維生素每日需要量少，能否推論它不重要？", steps: ["區分需要量大小與生理必要性。", "檢查推論是否有缺乏影響的證據。"], answer: "不能", why: "需求量少只表示所需質量較小，不表示功能可省略；維生素參與正常生理調節，長期缺乏仍可能造成明顯影響。" },
  ],
  [
    { belief: "維生素可以直接提供大量熱量。", whyWrong: "維生素主要參與生理調節，不是細胞呼吸主要使用的供能原料。", correction: "需要活動能量時應連結醣類等供能養分，不把維生素當燃料。" },
    { belief: "所有礦物質在人體內的功能都相同。", whyWrong: "鈣、鐵等礦物質的組成位置與生理角色各有差異。", correction: "依題幹提供的骨骼、牙齒或血紅素等線索辨識特定礦物質。" },
    { belief: "水只是解渴，沒有其他生理角色。", whyWrong: "水還是體液成分、物質運輸與反應介質，也參與調節體溫。", correction: "把水理解為組成、溶解、運輸、反應與體溫調節的重要條件。" },
    { belief: "需要量少的養分可以完全不攝取。", whyWrong: "需要量少不代表不需要，長期缺乏仍會使正常生理作用受影響。", correction: "評估養分要同時看種類、功能與適量，不能只按質量判斷重要性。" },
  ],
  [
    { prompt: "鐵在養分類別中屬於什麼？", answer: "礦物質", reason: "鐵是人體所需的礦物質，並參與血紅素的組成。" },
    { prompt: "水能否像醣類一樣直接提供能量？", answer: "不能", reason: "水是介質與身體組成，不是細胞呼吸分解利用的燃料。" },
    { prompt: "每日需求量少是否表示維生素不重要？", answer: "否", reason: "維生素雖需求量通常較少，仍參與維持正常生理作用。" },
  ],
));

questions.push(
  question("BIO_R4_Q_042_01", "BIO_R4_S042", "foundation", "下列哪一項最符合維生素在人體中的基本角色？", ["參與維持正常生理作用", "提供骨骼全部重量", "直接輸送神經衝動", "成為主要活動燃料"], 0, ["維生素常參與多種生理作用的調節。", "骨骼組成不能全歸因於維生素。", "神經衝動不是維生素直接輸送。", "主要活動燃料通常不是維生素。"], ["題目問基本角色，維生素與正常生理調節的連結最符合課程範圍。", "其他選項使用全部、直接或主要等錯誤功能描述，均不能成立。"]),
  question("BIO_R4_Q_042_02", "BIO_R4_S042", "foundation", "鈣與鐵在六大養分分類中，皆屬於下列哪一類？", ["維生素", "礦物質", "醣類", "脂質"], 1, ["鈣與鐵不是有機維生素。", "鈣與鐵都屬人體所需礦物質。", "醣類不是元素鈣與鐵的分類。", "脂質與鈣鐵的類別不同。"], ["鈣、鐵都是元素名稱，在營養分類中共同歸為礦物質。", "其餘三類的化學與生理分類都不同，沒有另一個可接受答案。"]),
  question("BIO_R4_Q_042_03", "BIO_R4_S042", "foundation", "人體內許多物質需先溶於體液再運送，最直接需要哪種養分？", ["蛋白質", "脂質", "水分", "澱粉"], 2, ["蛋白質不是普遍溶解介質。", "脂質不構成多數體液的主要介質。", "水可作為物質溶解與運輸的介質。", "澱粉需先消化，不能作為體液介質。"], ["題幹同時出現體液、溶解和運送，三個線索都指向水。", "其他選項可能是被運送或消化的物質，並非題目所問介質。"]),
  question("BIO_R4_Q_042_04", "BIO_R4_S042", "standard", "關於水的功能，下列敘述何者正確？", ["水只在口渴時才有作用", "水可直接取代所有養分", "水是人體最主要的熱量來源", "水可作為反應環境並協助體溫調節"], 3, ["水持續參與體內多種作用。", "水不能取代構造與供能養分。", "水本身不提供可利用熱量。", "水是反應介質並可透過汗液參與散熱。"], ["「水可作為反應環境並協助體溫調節」同時陳述水的反應介質與體溫調節角色，內容完整正確。", "「水只在口渴時才有作用」、「水可直接取代所有養分」、「水是人體最主要的熱量來源」把水限縮為解渴、誇大為取代物或誤認為能量來源。"]),
  question("BIO_R4_Q_042_05", "BIO_R4_S042", "standard", "某人長期鐵攝取不足，最可能直接影響哪一種物質的形成？", ["血紅素", "澱粉", "膽汁", "汗液"], 0, ["鐵是血紅素的重要組成相關物質。", "人體不會把鐵直接合成澱粉。", "膽汁形成不以鐵為直接材料。", "汗液主要含水與少量鹽類。"], ["依國中課程連結，鐵不足最直接影響血紅素形成與運氧相關功能。", "其他選項沒有題幹所給鐵元素與產物之間的直接組成關係。"]),
  question("BIO_R4_Q_042_06", "BIO_R4_S042", "standard", "比較維生素與礦物質，下列哪項敘述最合理？", ["兩者都是主要供能原料", "兩者需求量可能不大但都不可忽略", "兩者在人體中的功能完全一致", "兩者都只負責形成骨骼"], 1, ["兩者都不是主要供能燃料。", "所需量小仍可能是維持生理所必需。", "不同物質具有不同生理角色。", "只有部分礦物質與骨骼較直接相關。"], ["「兩者需求量可能不大但都不可忽略」正確區分需求量與必要性，也沒有把多樣功能過度簡化。", "「兩者都是主要供能原料」、「兩者在人體中的功能完全一致」、「兩者都只負責形成骨骼」誤認供能、宣稱完全相同，或把全部功能限縮為骨骼。"]),
  question("BIO_R4_Q_042_07", "BIO_R4_S042", "standard", "炎熱天氣運動後大量流汗，若只考慮最直接流失，應優先補充什麼？", ["額外脂肪", "大量蛋白粉", "適量水分", "更多澱粉"], 2, ["脂肪不是汗液主要流失成分。", "蛋白質並非口渴與汗液流失的直接補充。", "流汗直接造成水分流失，應適量補水。", "澱粉可供能但不是直接補回汗液水分。"], ["題目限定最直接流失，汗液造成水分離開人體，因此選適量水分。", "「額外脂肪」、「大量蛋白粉」、「更多澱粉」可能涉及其他營養需求，卻不回應題幹的水分流失。"]),
  question("BIO_R4_Q_042_08", "BIO_R4_S042", "advanced", "學生說「維生素吃得越多，得到的能量越多」，錯誤的關鍵是什麼？", ["維生素不存在於食物中", "人體完全不需要維生素", "所有維生素都由人體大量製造", "把調節生理作用誤當成直接供能"], 3, ["多種食物確實可以含維生素。", "人體需要適量維生素維持生理。", "不能概括為全部都由人體大量製造。", "維生素的調節角色不等於能量燃料。"], ["此說法把攝取量與能量錯誤連結，核心混淆是調節作用與直接供能。", "「維生素不存在於食物中」、「人體完全不需要維生素」、「所有維生素都由人體大量製造」都是另一種過度或錯誤陳述，不能精準指出原句推理問題。"]),
  question("BIO_R4_Q_042_09", "BIO_R4_S042", "advanced", "某飲食方案熱量充足卻完全缺少礦物質，最合理的評估為何？", ["仍可能使正常生理與身體組成受影響", "熱量足夠就一定完全健康", "礦物質只影響食物甜味", "身體可用水取代所有礦物質"], 0, ["礦物質缺乏仍可能影響組成與生理作用。", "熱量不是評估營養完整性的唯一指標。", "礦物質功能不能簡化為甜味。", "水不能取代鈣鐵等特定物質。"], ["總熱量充足不代表各類養分齊全，缺少礦物質仍可能產生影響。", "其他選項都假設熱量或水可取代特定養分，違反均衡概念。"]),
  question("BIO_R4_Q_042_10", "BIO_R4_S042", "advanced", "下列哪個證據最能支持水參與人體的物質運輸？", ["皮下脂肪能保溫", "血漿含大量水並攜帶多種溶解物質", "牙齒含有礦物質", "肌肉組織含蛋白質"], 1, ["皮下脂肪說明脂質保溫功能。", "含水血漿攜帶溶質直接支持運輸功能。", "牙齒組成不能證明水參與運輸。", "肌肉蛋白質也不呈現水的運輸角色。"], ["血漿中的水與其中溶解物質共同呈現水作為運輸介質的證據。", "「皮下脂肪能保溫」、「牙齒含有礦物質」、「肌肉組織含蛋白質」描述其他養分或構造，與水攜帶物質沒有直接連結。"]),
  question("BIO_R4_Q_042_11", "BIO_R4_S042", "transfer", "設計校園飲水宣導時，哪句話的生物概念最正確？", ["喝水可以取代每一餐", "水喝越多必然越健康", "水參與運輸與調溫，應依活動與環境適量補充", "只有感到極度口渴才需要水"], 2, ["水不能提供全部養分與能量。", "攝取仍應適量，不能無限制增加。", "此說法兼顧水的功能與情境需求。", "身體在極度口渴前已持續需要水。"], ["宣導應正確說明功能並避免絕對化，「水參與運輸與調溫，應依活動與環境適量補充」符合兩項要求。", "其他句子都把水誇大為取代品、無限有益，或把需求限於極端口渴。"]),
  question("BIO_R4_Q_042_12", "BIO_R4_S042", "transfer", "荒野活動者有食物卻長時間無法取得水，最先應重視哪個風險？", ["立即失去所有骨骼礦物質", "維生素立刻轉成脂肪", "蛋白質完全停止存在", "體液與散熱等作用因缺水受影響"], 3, ["骨骼礦物質不會因短期缺水立即全部消失。", "維生素不會因缺水立刻轉成脂肪。", "身體蛋白質不會瞬間完全不存在。", "缺水會直接影響體液、運輸與體溫調節。"], ["題幹限定有食物但無水，最直接風險是依賴水的體液與散熱作用。", "「立即失去所有骨骼礦物質」、「維生素立刻轉成脂肪」、「蛋白質完全停止存在」都使用立即、完全等不合理敘述，也缺乏相應生理機制。"]),
);

